window.SUPER_BANK.push(...[{"id":"chapter-3/data.js:ss04","mode":"safety","topic":"Safety & role","format":"scenario","prompt":"A colleague proposes tying a resident with dementia to a chair because the resident wanders. What is the safest response?","choices":["Do not use an unauthorized restraint; stay attentive, seek immediate team support and report the concern.","Use the restraint briefly while remaining in the room.","Ask the family to authorize the restraint verbally.","Try the restraint first and document it if it seems to work."],"answer":[0],"explain":"The course scenario says not to use unauthorized restraint. Protect dignity, seek support and report the unsafe suggestion through appropriate channels.","source":"Part Two notes, Assignment 1 scenario 3","originalId":"ss04","group":"Chapter 3","bank":"Chapters 2 & 3","sourceFiles":["chapter-3/data.js"],"references":[]},{"id":"chapter-3/data.js:ss05","mode":"safety","topic":"Safety & role","format":"scenario","prompt":"A client requests a household task that is not in the care plan and may fall outside your assigned duties. What is the best response?","choices":["Explain that you need to follow the care plan and agency policy, then check with the supervisor.","Do the task once because it seems harmless, then ask about it later.","Ask the family to approve it so the plan does not need to change.","Add the task to the care plan because the client requested it."],"answer":[0],"explain":"The notes stress following policy, care plans, training, competence and supervision. A caring relationship does not authorize extra duties.","source":"First-Half Quiz Study Guide, section 11; Part Two notes, section 5","originalId":"ss05","group":"Chapter 3","bank":"Chapters 2 & 3","sourceFiles":["chapter-3/data.js"],"references":[]},{"id":"chapter-3/data.js:ss06","mode":"safety","topic":"Safety & role","format":"scenario","prompt":"Several clients need care at once, and one transfer requires two workers. What is the safest way to manage the competing needs?","choices":["Prioritize immediate risks, coordinate with the team and get the second worker before starting the transfer.","Complete the transfer alone so the client is not kept waiting.","Do routine tasks first because they take less time, then reassess urgent needs.","Promise each client an immediate visit before checking staff availability."],"answer":[0],"explain":"The instructor emphasized prioritizing client needs and asking for help when necessary. Work with colleagues and follow transfer instructions.","source":"HCA 200 Introduction study chat; Part Two notes, section 3","originalId":"ss06","group":"Chapter 3","bank":"Chapters 2 & 3","sourceFiles":["chapter-3/data.js"],"references":[]},{"id":"chapter-3/data.js:ss07","mode":"safety","topic":"Safety & role","format":"scenario","prompt":"A reporter asks you for information about a former client. What is the appropriate response?","choices":["Protect the person’s confidentiality and refer the reporter to an authorized contact.","Confirm only details that seem harmless, such as the person’s former unit.","Share information if the reporter promises not to publish it.","Confirm the person received care but withhold the diagnosis."],"answer":[0],"explain":"The course ethical scenario directs students to protect confidentiality and refer media inquiries to an authorized contact.","source":"Part Two notes, Assignment 1 scenario 1","originalId":"ss07","group":"Chapter 3","bank":"Chapters 2 & 3","sourceFiles":["chapter-3/data.js"],"references":[]},{"id":"chapter-3/data.js:b01","mode":"boundaries","topic":"Boundaries","format":"scenario","prompt":"After a scheduled home-care visit ends, a client who seems lonely invites you to stay for an unpaid chat. What is the most professional response?","choices":["Respond kindly, keep to the authorized visit and care plan, and discuss ongoing social-support needs with the team.","Stay off the clock if the client says they have no one else to talk to.","Promise to return privately so the client has reliable company.","Avoid documenting or discussing the request to protect the client’s feelings."],"answer":[0],"explain":"Home care takes place in a private, informal-feeling space, so boundaries can be harder to maintain. Kindness and clear professional limits can coexist.","source":"HCA 200 Introduction study chat; First-Half Quiz Study Guide, section 11","originalId":"b01","group":"Chapter 3","bank":"Chapters 2 & 3","sourceFiles":["chapter-3/data.js"],"references":[]},{"id":"chapter-3/data.js:b02","mode":"boundaries","topic":"Boundaries","format":"scenario","prompt":"A client’s relative asks you to send health updates from your personal phone. What should guide your response?","choices":["Check consent, confidentiality rules and agency communication policy; use authorized channels and involve the care team.","Send the update if the relative knows the client’s diagnosis.","Share only brief details and delete the message afterward.","Post a general update in the family chat without using the client’s name."],"answer":[0],"explain":"Confidentiality and employer policy guide information sharing. Direct health updates should go through authorized channels, not a personal informal arrangement.","source":"Part Two notes, sections 5 and 6","originalId":"b02","group":"Chapter 3","bank":"Chapters 2 & 3","sourceFiles":["chapter-3/data.js"],"references":[]},{"id":"chapter-3/data.js:b03","mode":"boundaries","topic":"Boundaries","format":"scenario","prompt":"A family requests extra cleaning that is not assigned in the care plan. What is the best response?","choices":["Explain your assigned duties respectfully and check with the supervisor about the request.","Do it once because the family is present and can supervise.","Trade the extra cleaning for another task the client does not need.","Ask another client whether the task is normally included."],"answer":[0],"explain":"Household tasks need clear limits. Follow the assigned care plan and agency policy; ask a supervisor when the request is unclear.","source":"First-Half Quiz Study Guide, section 11","originalId":"b03","group":"Chapter 3","bank":"Chapters 2 & 3","sourceFiles":["chapter-3/data.js"],"references":[]},{"id":"chapter-3/data.js:b04","mode":"boundaries","topic":"Boundaries","format":"scenario","prompt":"A family offers you an expensive personal gift as thanks. What should guide your response?","choices":["Employer policy and professional boundaries; ask a supervisor if the policy is unclear.","Accept it privately because refusing may offend the family.","Accept it as long as you do not provide extra care in return.","Decline without checking policy or discussing the situation with anyone."],"answer":[0],"explain":"The available notes emphasize professional boundaries with clients and families. They do not give one universal gift rule, so check employer policy and supervision before responding.","source":"Part Two notes, section 5 (policy-specific detail)","originalId":"b04","group":"Chapter 3","bank":"Chapters 2 & 3","sourceFiles":["chapter-3/data.js"],"references":[]},{"id":"chapter-3/data.js:b05","mode":"boundaries","topic":"Boundaries","format":"scenario","prompt":"A client asks you to perform a care task you have not been trained to do. What should you do before acting?","choices":["Pause and check the care plan, your competence, agency policy and supervisor direction.","Try the task carefully because the client trusts you.","Ask the client or family to demonstrate the technique.","Proceed if another worker says it is usually straightforward."],"answer":[0],"explain":"Trust does not replace training or authorization. The notes direct HCAs to follow competence, care plans, policy and supervision, and to ask when unsure.","source":"First-Half Quiz Study Guide, section 11; Part Two notes, section 5","originalId":"b05","group":"Chapter 3","bank":"Chapters 2 & 3","sourceFiles":["chapter-3/data.js"],"references":[]},{"id":"chapter-3/data.js:b06","mode":"boundaries","topic":"Boundaries","format":"scenario","prompt":"A client repeats requests that are frustrating you. Which response protects the client’s dignity and your professional boundaries?","choices":["Respond respectfully, keep the agreed care limits and seek team support if a care or safety concern is emerging.","Ignore further requests so the client learns not to repeat them.","Promise special treatment next visit to end the conversation.","Discuss the client’s behaviour where other residents can hear."],"answer":[0],"explain":"The notes say frustration does not justify gossip, abuse or unsafe shortcuts. Use appropriate professional channels for legitimate care concerns.","source":"Part Two notes, Assignment 1 scenarios 2 and 3","originalId":"b06","group":"Chapter 3","bank":"Chapters 2 & 3","sourceFiles":["chapter-3/data.js"],"references":[]},{"id":"chapter-3/data.js:w01","mode":"safety","topic":"Benefits & challenges","format":"choice","prompt":"A care site has several professionals available nearby, but decisions still require coordination. Which benefit is most directly created by their physical proximity?","choices":["Prompt communication and access to team support.","Automatic agreement about every client’s priorities.","Independent authority to change another professional’s plan.","Removal of the need to report changes formally."],"answer":[0],"explain":"Nearby professionals can facilitate coordination. Their presence does not remove reporting duties, role boundaries or the need to resolve differences.","source":"Workplace Setting slide 21; Part Two notes, section 1","originalId":"w01","group":"Chapter 3","bank":"Chapters 2 & 3","sourceFiles":["chapter-3/data.js"],"references":[]},{"id":"chapter-3/data.js:w02","mode":"safety","topic":"Benefits & challenges","format":"choice","prompt":"A care site has to help shared spaces feel familiar and home-like while meeting facility routines. Which workplace challenge does this describe?","choices":["Making the site feel like home","Coordinating with nearby health professionals","Providing community-based home care","Offering respite to a family caregiver"],"answer":[0],"explain":"“Making the site feel like home” is explicitly listed as a challenge associated with working in a site.","source":"Workplace Setting slide 21","originalId":"w02","group":"Chapter 3","bank":"Chapters 2 & 3","sourceFiles":["chapter-3/data.js"],"references":[]},{"id":"chapter-3/data.js:w03","mode":"safety","topic":"Benefits & challenges","format":"choice","prompt":"A facility worker supports distressed clients and families while managing personal emotional reactions. Which workplace challenge is most directly illustrated?","choices":["Responding professionally to people in distress.","Coordinating access to nearby health professionals.","Creating an individualized physical environment.","Adapting to changes between evening and night shifts."],"answer":[0],"explain":"The facility-workplace list identifies dealing with people in distress as a challenge. Other listed workplace issues concern different aspects of the job.","source":"Chapter 3, “Benefits and Challenges Associated With Working in a Facility” (p. 43)","originalId":"w03","group":"Chapter 3","bank":"Chapters 2 & 3","sourceFiles":["chapter-3/data.js"],"references":[]},{"id":"chapter-3/data.js:w04","mode":"safety","topic":"Benefits & challenges","format":"choice","prompt":"Several clients need assistance during a busy shift. Which response best addresses the site-work challenge of competing demands?","choices":["Assess immediate risks, prioritize needs and coordinate available team support.","Finish the shortest tasks first so the completed-task count rises quickly.","Attend to clients in request order without reassessing urgency.","Keep the original sequence unchanged so each client receives predictable timing."],"answer":[0],"explain":"Managing many needs in limited time requires judgment and coordination rather than a fixed convenience-based sequence.","source":"Workplace Setting slide 21","originalId":"w04","group":"Chapter 3","bank":"Chapters 2 & 3","sourceFiles":["chapter-3/data.js"],"references":[]},{"id":"chapter-3/data.js:m01","chapter":2,"mode":"medicare","topic":"Canada’s Medicare","format":"choice","prompt":"A student says Medicare is funded mainly by premiums paid directly by each patient. Which description is more accurate?","choices":["Public funds come through federal and provincial or territorial taxes.","Most funding comes from private insurance premiums.","Municipal property taxes pay for the full national plan.","Patients are billed the full cost of insured visits."],"answer":[0],"explain":"The chapter describes Medicare as publicly funded through federal and provincial or territorial taxes. The governments share responsibilities in the system.","source":"Chapter 2 textbook, “Canada’s Current Health Care System”; Therese quiz review","originalId":"m01","group":"Chapter 2","bank":"Chapters 2 & 3","sourceFiles":["chapter-3/data.js"],"references":[]},{"id":"chapter-3/data.js:m02","chapter":2,"mode":"medicare","topic":"Canada’s Medicare","format":"choice","prompt":"A medically necessary service is covered under Canada’s core public plan. Which pair of services is at the centre of Medicare coverage?","choices":["Hospital and physician services","Prescription drugs and private home care","Dental and vision services","Every service offered by a health practitioner"],"answer":[0],"explain":"The textbook centers Medicare on insured medically necessary hospital and physician services. Supplementary benefits and private plans may cover other services, with eligibility and coverage varying.","source":"Chapter 2 textbook, “Canada’s Current Health Care System” and “Additional Services”","originalId":"m02","group":"Chapter 2","bank":"Chapters 2 & 3","sourceFiles":["chapter-3/data.js"],"references":[]},{"id":"chapter-3/data.js:m03","chapter":2,"mode":"medicare","topic":"Canada’s Medicare","format":"choice","prompt":"A province runs its own health-insurance plan. Which federal action supports the national health-care framework?","choices":["Administering the Canada Health Act and transferring funding to provinces and territories","Operating each provincial insurance plan day to day","Deciding which hospitals each province must build","Setting individual clients’ home-care eligibility"],"answer":[0],"explain":"The federal role includes administering the Canada Health Act, providing funding, and carrying out national policies and programs. Provinces and territories administer their own insurance plans.","source":"Chapter 2 textbook, “The Federal Role in Health Care”; Therese quiz review","originalId":"m03","group":"Chapter 2","bank":"Chapters 2 & 3","sourceFiles":["chapter-3/data.js"],"references":[]},{"id":"chapter-3/data.js:m04","chapter":2,"mode":"medicare","topic":"Canada’s Medicare","format":"choice","prompt":"A new resident asks which government administers British Columbia’s Medical Services Plan. Who is responsible?","choices":["The provincial government","The federal government","A private insurer selected by the client","The municipal government"],"answer":[0],"explain":"Each province and territory develops and administers its own insurance plan and plans and finances its services under the Canada Health Act. BC’s plan is MSP.","source":"Chapter 2 textbook, “The Provincial or Territorial Role in Health Care”; First-Half Quiz Study Guide","originalId":"m04","group":"Chapter 2","bank":"Chapters 2 & 3","sourceFiles":["chapter-3/data.js"],"references":[]},{"id":"chapter-3/data.js:m05","chapter":2,"mode":"medicare","topic":"Canada Health Act","format":"choice","prompt":"Which Canada Health Act principle requires coverage of insured medically necessary hospital and physician services?","choices":["Comprehensiveness","Universality","Portability","Public administration"],"answer":[0],"explain":"Comprehensiveness concerns coverage of insured medically necessary services. For a quiz, distinguish it from universality (who is entitled) and accessibility (reasonable access).","source":"Chapter 2 textbook, Box 2.1; Therese quiz review","originalId":"m05","group":"Chapter 2","bank":"Chapters 2 & 3","sourceFiles":["chapter-3/data.js"],"references":[]},{"id":"chapter-3/data.js:m06","chapter":2,"mode":"medicare","topic":"Canada Health Act","format":"choice","prompt":"All eligible residents of a province are entitled to the plan’s insured services on similar terms. Which principle is this?","choices":["Universality","Comprehensiveness","Portability","Accessibility"],"answer":[0],"explain":"Universality describes eligible residents’ entitlement to insured services on similar terms. It does not mean every health service is insured.","source":"Chapter 2 textbook, Box 2.1","originalId":"m06","group":"Chapter 2","bank":"Chapters 2 & 3","sourceFiles":["chapter-3/data.js"],"references":[]},{"id":"chapter-3/data.js:m07","chapter":2,"mode":"medicare","topic":"Canada Health Act","format":"choice","prompt":"A client moves from Manitoba to Nova Scotia and asks whether provincial coverage simply disappears during the move. Which principle is most relevant?","choices":["Portability","Public administration","Comprehensiveness","Universality"],"answer":[0],"explain":"Portability concerns continuing coverage when travelling or moving, subject to applicable rules. The chapter says people must notify their old jurisdiction and register with the new one; transitional coverage has limits.","source":"Chapter 2 textbook, Box 2.1 and “Supporting Mr. Wloch”; Therese quiz review","originalId":"m07","group":"Chapter 2","bank":"Chapters 2 & 3","sourceFiles":["chapter-3/data.js"],"references":[]},{"id":"chapter-3/data.js:m08","chapter":2,"mode":"medicare","topic":"Canada Health Act","format":"choice","prompt":"A person’s income, age or health status should not create an improper financial barrier to an insured service. Which principle is the best match?","choices":["Accessibility","Universality","Public administration","Comprehensiveness"],"answer":[0],"explain":"Accessibility concerns reasonable access to insured services without prohibited financial barriers. It does not promise that every service or every wait time is the same.","source":"Chapter 2 textbook, Box 2.1; Therese quiz review","originalId":"m08","group":"Chapter 2","bank":"Chapters 2 & 3","sourceFiles":["chapter-3/data.js"],"references":[]},{"id":"chapter-3/data.js:m09","chapter":2,"mode":"medicare","topic":"Canada Health Act","format":"choice","prompt":"A provincial insurance plan is operated by a public authority on a nonprofit basis. Which principle does this illustrate?","choices":["Public administration","Portability","Comprehensiveness","Accessibility"],"answer":[0],"explain":"Public administration means the insurance plan is run by a public organization on a nonprofit basis and is accountable to the public and government.","source":"Chapter 2 textbook, Box 2.1","originalId":"m09","group":"Chapter 2","bank":"Chapters 2 & 3","sourceFiles":["chapter-3/data.js"],"references":[]},{"id":"chapter-3/data.js:m10","chapter":2,"mode":"medicare","topic":"Canada’s Medicare","format":"choice","prompt":"Which leader is associated with Saskatchewan’s first public hospital-insurance plan in 1947?","choices":["Tommy Douglas","Lester B. Pearson","Pierre Trudeau","John Diefenbaker"],"answer":[0],"explain":"The textbook associates Saskatchewan’s 1947 hospital-insurance plan with Premier Tommy Douglas. Therese also specifically told students to remember him.","source":"Chapter 2 textbook, “Evolution of Canada’s Health Care System”; Therese quiz review","originalId":"m10","group":"Chapter 2","bank":"Chapters 2 & 3","sourceFiles":["chapter-3/data.js"],"references":[]},{"id":"chapter-3/data.js:m11","chapter":2,"mode":"medicare","topic":"Canada’s Medicare","format":"choice","prompt":"In what year was the Canada Health Act passed?","choices":["1984","1947","1966","1972"],"answer":[0],"explain":"The Canada Health Act is dated 1984 in the course materials. Keep it distinct from Saskatchewan’s 1947 hospital plan and the 1972 expansion of insured medical services described in the chapter.","source":"Chapter 2 textbook, Key Terms; First-Half Quiz Study Guide","originalId":"m11","group":"Chapter 2","bank":"Chapters 2 & 3","sourceFiles":["chapter-3/data.js"],"references":[]},{"id":"chapter-3/data.js:m12","chapter":2,"mode":"medicare","topic":"Canada’s Medicare","format":"choice","prompt":"By 1972, what major expansion of insured medical services had taken place across the provinces and territories?","choices":["Plans had extended coverage to medical services outside hospitals.","Saskatchewan had introduced its first public hospital-insurance plan.","The Canada Health Act had been passed.","Private insurance had replaced provincial plans."],"answer":[0],"explain":"The textbook describes 1972 as the point by which all provinces and territories had extended their plans to cover medical services outside hospitals, marking modern Medicare.","source":"Chapter 2 textbook, “Evolution of Canada’s Health Care System”","originalId":"m12","group":"Chapter 2","bank":"Chapters 2 & 3","sourceFiles":["chapter-3/data.js"],"references":[]},{"id":"chapter-3/data.js:m13","chapter":2,"mode":"medicare","topic":"Canada’s Medicare","format":"choice","prompt":"What is the purpose of federal tax transfers to provincial and territorial health systems?","choices":["To share the cost of eligible health services within the national framework","To pay every private home-care invoice directly","To let the federal government administer every local clinic","To replace provincial and territorial insurance plans"],"answer":[0],"explain":"The federal government transfers funding to help provinces and territories share costs. Provincial and territorial governments still plan and administer their own insurance plans.","source":"Chapter 2 textbook, “The Federal Role in Health Care”","originalId":"m13","group":"Chapter 2","bank":"Chapters 2 & 3","sourceFiles":["chapter-3/data.js"],"references":[]},{"id":"chapter-3/data.js:m14","chapter":2,"mode":"medicare","topic":"Canada’s Medicare","format":"choice","prompt":"Which group receives direct health services through some federal programs?","choices":["Serving members of the Canadian Forces","All residents enrolled in a provincial plan","Every person receiving home care","Anyone with employer-sponsored insurance"],"answer":[0],"explain":"The federal government directly delivers services to certain groups, including serving Canadian Forces members, RCMP members, eligible veterans, inmates of federal penitentiaries, and some First Nations and Inuit groups.","source":"Chapter 2 textbook, “The Federal Role in Health Care”","originalId":"m14","group":"Chapter 2","bank":"Chapters 2 & 3","sourceFiles":["chapter-3/data.js"],"references":[]},{"id":"chapter-3/data.js:m15","chapter":2,"mode":"medicare","topic":"Canada’s Medicare","format":"choice","prompt":"Which partners can share responsibility for Indigenous health services?","choices":["Federal, provincial and territorial governments, together with Indigenous organizations","The federal government alone for every service","Provincial governments alone for every community","Private insurers and municipal governments only"],"answer":[0],"explain":"The chapter describes Indigenous health responsibilities as shared among federal, provincial and territorial governments and Indigenous organizations. Responsibilities also vary by service and community.","source":"Chapter 2 textbook, “Canada’s Current Health Care System” and Indigenous health section","originalId":"m15","group":"Chapter 2","bank":"Chapters 2 & 3","sourceFiles":["chapter-3/data.js"],"references":[]},{"id":"chapter-3/data.js:m16","chapter":2,"mode":"medicare","topic":"Indigenous health","format":"choice","prompt":"Which option best captures the range of barriers that can interact to limit access to health services for some Indigenous communities?","choices":["Geography, language or cultural barriers, socioeconomic conditions and jurisdictional complexity","Geography and distance from providers alone","Language and cultural differences alone","Jurisdictional complexity without historical or socioeconomic factors"],"answer":[0],"explain":"The chapter discusses geographic, organizational, language, cultural and socioeconomic barriers, alongside the effects of historical policies. Avoid reducing the issue to one cause.","source":"Chapter 2 textbook, Indigenous health section; Chapter 2 slides 5–8","originalId":"m16","group":"Chapter 2","bank":"Chapters 2 & 3","sourceFiles":["chapter-3/data.js"],"references":[]},{"id":"chapter-3/data.js:m17","chapter":2,"mode":"medicare","topic":"Indigenous health","format":"choice","prompt":"Which set names the four dimensions in the holistic Indigenous health model?","choices":["Physical, mental, emotional and spiritual","Physical, social, financial and occupational","Family, community, language and land","Primary, secondary, tertiary and quaternary"],"answer":[0],"explain":"The chapter describes Indigenous health and wellness through balance and relationships among physical, mental, emotional and spiritual aspects.","source":"Chapter 2 textbook, Indigenous health section; Therese quiz review","originalId":"m17","group":"Chapter 2","bank":"Chapters 2 & 3","sourceFiles":["chapter-3/data.js"],"references":[]},{"id":"chapter-3/data.js:m18","chapter":2,"mode":"medicare","topic":"Indigenous health","format":"choice","prompt":"A client asks to include a traditional healing practice in their care. Which response best supports culturally safe, client-led care?","choices":["Listen to the client and collaborate with requested healers, while coordinating with the care team.","Assume the client wants the same practices as other Indigenous clients.","Include the practice only if it replaces prescribed treatment.","Ask the family to decide without consulting the client."],"answer":[0],"explain":"The chapter calls for recognizing the value of Indigenous healing practices and collaborating with healers and Elders when the patient requests it. Cultural respect does not mean making assumptions about an individual.","source":"Chapter 2 textbook, TRC Health Calls to Action; Therese quiz review","originalId":"m18","group":"Chapter 2","bank":"Chapters 2 & 3","sourceFiles":["chapter-3/data.js"],"references":[]},{"id":"chapter-3/data.js:m19","chapter":2,"mode":"medicare","topic":"Indigenous health","format":"choice","prompt":"Which action aligns with the Truth and Reconciliation Commission’s health-related calls to action?","choices":["Support culturally safe care and recognize Indigenous healing practices when requested.","Require all Indigenous clients to choose the same treatment.","Replace community care with hospital care in every case.","Limit Indigenous participation in health professions."],"answer":[0],"explain":"The calls include addressing health inequities, recognizing Indigenous healing practices when requested, increasing Indigenous health professionals, and cultural competency education.","source":"Chapter 2 textbook, Box 2.4","originalId":"m19","group":"Chapter 2","bank":"Chapters 2 & 3","sourceFiles":["chapter-3/data.js"],"references":[]},{"id":"chapter-3/data.js:h01","chapter":2,"mode":"pathways","topic":"Care delivery","format":"choice","prompt":"A person first contacts a family doctor or nurse practitioner for prevention, early diagnosis or a new concern. Which level of care is this?","choices":["Primary care","Secondary care","Tertiary care","Quaternary care"],"answer":[0],"explain":"Primary health care is generally the first point of contact and includes prevention, health promotion and early diagnosis. It can occur in the community and sometimes in a hospital.","source":"Chapter 2 textbook, “Primary, Secondary, and Tertiary Health Care Delivery”; Therese quiz review","originalId":"h01","group":"Chapter 2","bank":"Chapters 2 & 3","sourceFiles":["chapter-3/data.js"],"references":[]},{"id":"chapter-3/data.js:h02","chapter":2,"mode":"pathways","topic":"Care delivery","format":"choice","prompt":"A family physician refers a client to a cardiologist for assessment and treatment of a specific heart problem. Which level is this?","choices":["Secondary care","Primary care","Tertiary care","Quaternary care"],"answer":[0],"explain":"Secondary care includes assessment, diagnosis and treatment for more complex issues, often through referral to a specialist. It can happen in a specialist’s community office or a hospital.","source":"Chapter 2 textbook, “Primary, Secondary, and Tertiary Health Care Delivery”; Therese quiz review","originalId":"h02","group":"Chapter 2","bank":"Chapters 2 & 3","sourceFiles":["chapter-3/data.js"],"references":[]},{"id":"chapter-3/data.js:h03","chapter":2,"mode":"pathways","topic":"Care delivery","format":"choice","prompt":"A client needs highly specialized treatment in a teaching hospital’s critical-care unit. Which level best fits?","choices":["Tertiary care","Primary care","Secondary care","Quaternary care"],"answer":[0],"explain":"Tertiary care is highly specialized and technical, usually in large research or teaching hospitals. Therese highlighted that it is the most expensive level in the three-level comparison.","source":"Chapter 2 textbook, “Primary, Secondary, and Tertiary Health Care Delivery”; Therese quiz review","originalId":"h03","group":"Chapter 2","bank":"Chapters 2 & 3","sourceFiles":["chapter-3/data.js"],"references":[]},{"id":"chapter-3/data.js:h04","chapter":2,"mode":"pathways","topic":"Care delivery","format":"choice","prompt":"A few specialized centres offer an experimental treatment that goes beyond the usual tertiary-care services. Which level describes it?","choices":["Quaternary care","Primary care","Secondary care","Home care"],"answer":[0],"explain":"Quaternary care is described as an even more specialized extension of tertiary care and may include experimental medicines or procedures.","source":"Chapter 2 textbook, “Primary, Secondary, and Tertiary Health Care Delivery”","originalId":"h04","group":"Chapter 2","bank":"Chapters 2 & 3","sourceFiles":["chapter-3/data.js"],"references":[]},{"id":"chapter-3/data.js:h05","chapter":2,"mode":"pathways","topic":"Care delivery","format":"choice","prompt":"A nurse provides health advice by phone or video and directs callers to appropriate services. What is this way of delivering care called?","choices":["Telehealth","Secondary care","Tertiary care","Home care"],"answer":[0],"explain":"Telehealth provides phone- or computer-based access to health advice and primary-care support. Therese used BC’s 811 service as a class example.","source":"Chapter 2 textbook, “Primary, Secondary, and Tertiary Health Care Delivery”; Therese quiz review (811 example)","originalId":"h05","group":"Chapter 2","bank":"Chapters 2 & 3","sourceFiles":["chapter-3/data.js"],"references":[]},{"id":"chapter-3/data.js:h06","chapter":2,"mode":"pathways","topic":"Care delivery","format":"choice","prompt":"A hospital provides emergency treatment, specialist consultations and highly specialized procedures. Which statement best explains how to classify these services?","choices":["Classify each service by its level and complexity; the building alone does not determine the level.","Classify every hospital service as tertiary because it happens in a hospital.","Classify care only by the professional who first referred the client.","Classify home care as secondary because it happens outside a clinic."],"answer":[0],"explain":"Hospitals can provide more than one level of care. Primary, secondary and tertiary describe the kind and complexity of services, not simply the building.","source":"Chapter 2 textbook, Figure 2.3; Therese quiz review","originalId":"h06","group":"Chapter 2","bank":"Chapters 2 & 3","sourceFiles":["chapter-3/data.js"],"references":[]},{"id":"chapter-3/data.js:h07","chapter":2,"mode":"pathways","topic":"Health promotion & prevention","format":"choice","prompt":"A school offers hepatitis B immunization to prevent infection. What type of intervention is this?","choices":["Disease prevention","Health promotion only","Tertiary treatment","Supplementary insurance"],"answer":[0],"explain":"Immunization is a disease-prevention measure. Therese specifically used hepatitis B vaccination in elementary school as a class example.","source":"Chapter 2 textbook, “Health Promotion and Disease Prevention”; Therese quiz review","originalId":"h07","group":"Chapter 2","bank":"Chapters 2 & 3","sourceFiles":["chapter-3/data.js"],"references":[]},{"id":"chapter-3/data.js:h08","chapter":2,"mode":"pathways","topic":"Health promotion & prevention","format":"choice","prompt":"Which distinction between health promotion and disease prevention is most accurate?","choices":["Promotion supports or improves health and well-being; prevention aims to reduce the chance of illness or injury.","Promotion begins only after a diagnosis; prevention applies only in hospitals.","Promotion and prevention are interchangeable terms for treatment.","Prevention focuses on well-being, while promotion only prevents infection."],"answer":[0],"explain":"The chapter distinguishes strategies that improve or maintain health and independence from strategies that prevent disease or injury. They are related but not identical.","source":"Chapter 2 textbook, “Health Promotion and Disease Prevention”; Therese quiz review","originalId":"h08","group":"Chapter 2","bank":"Chapters 2 & 3","sourceFiles":["chapter-3/data.js"],"references":[]},{"id":"chapter-3/data.js:h09","chapter":2,"mode":"pathways","topic":"Health promotion & prevention","format":"choice","prompt":"A support worker follows directions to keep a bedbound client’s skin clean and dry, reposition them and assist with range-of-motion exercises. What is the main preventive purpose?","choices":["Reduce avoidable complications, such as pressure injuries, while supporting well-being","Provide tertiary treatment without a clinician","Replace nursing assessment and care planning","Restore mobility by changing the client’s prescribed plan"],"answer":[0],"explain":"The textbook describes support workers contributing to prevention through nonmedical care such as skin care, repositioning and range-of-motion support, within assigned directions and competence.","source":"Chapter 2 textbook, “Health Promotion and Disease Prevention”","originalId":"h09","group":"Chapter 2","bank":"Chapters 2 & 3","sourceFiles":["chapter-3/data.js"],"references":[]},{"id":"chapter-3/data.js:h10","chapter":2,"mode":"pathways","topic":"Health promotion & prevention","format":"choice","prompt":"Which action is the clearest example of health promotion rather than prevention or treatment?","choices":["Giving people information and resources that support healthy choices and well-being","Offering hepatitis B vaccination to reduce infection risk","Screening for a disease to detect it early","Performing surgery to treat an established injury"],"answer":[0],"explain":"Health promotion provides information and tools that help people make choices supporting health and wellness. Prevention and promotion are important system functions, not only post-illness treatment.","source":"Chapter 2 textbook, Key Terms and “Health Promotion and Disease Prevention”","originalId":"h10","group":"Chapter 2","bank":"Chapters 2 & 3","sourceFiles":["chapter-3/data.js"],"references":[]},{"id":"chapter-3/data.js:h11","chapter":2,"mode":"pathways","topic":"Home care","format":"choice","prompt":"A client receives health and support services in their own residence. What is this service arrangement called?","choices":["Home care","Tertiary care","Inpatient care","Private insurance"],"answer":[0],"explain":"Home care means health and support services provided to people in their places of residence. It is a major community-based service.","source":"Chapter 2 textbook, “Home Care”; Chapter 2 slides 19–21","originalId":"h11","group":"Chapter 2","bank":"Chapters 2 & 3","sourceFiles":["chapter-3/data.js"],"references":[]},{"id":"chapter-3/data.js:h12","chapter":2,"mode":"pathways","topic":"Home care","format":"choice","prompt":"Which outcome is a central goal of home-care services when the client’s needs can be met safely at home?","choices":["Maintain health and independence and, where appropriate, delay or avoid facility admission","Ensure that no client ever needs hospital or facility care","Limit support to nursing procedures only","Replace all family and community involvement"],"answer":[0],"explain":"Home care can maintain health and independence, replace some facility care, or delay or prevent admission when appropriate. Services depend on need and local program rules.","source":"Chapter 2 textbook, “Home Care”","originalId":"h12","group":"Chapter 2","bank":"Chapters 2 & 3","sourceFiles":["chapter-3/data.js"],"references":[]},{"id":"chapter-3/data.js:h13","chapter":2,"mode":"pathways","topic":"Home care","format":"choice","prompt":"Which group reflects the range of people who may receive home-care services, depending on local needs and program rules?","choices":["An older adult, a person recovering from illness, a person with a disability, or a family needing support","Only adults over 65 who live alone","Only people discharged after surgery","Only clients who pay privately"],"answer":[0],"explain":"The textbook describes home care for a wide range of people, including older adults, families, people with disabilities or medical conditions, and people recovering or receiving end-of-life support.","source":"Chapter 2 textbook, “Home Care”","originalId":"h13","group":"Chapter 2","bank":"Chapters 2 & 3","sourceFiles":["chapter-3/data.js"],"references":[]},{"id":"chapter-3/data.js:h14","chapter":2,"mode":"pathways","topic":"Home care","format":"choice","prompt":"A support worker helps a client bathe and dress at home. Which home-care service category does this illustrate?","choices":["Personal care","Professional therapy","Health-insurance administration","Tertiary treatment"],"answer":[0],"explain":"Personal-care services are nonmedical supports that may include help with ADLs and comfort care, including care for people who are dying.","source":"Chapter 2 textbook, “Home Care Services and Funding”","originalId":"h14","group":"Chapter 2","bank":"Chapters 2 & 3","sourceFiles":["chapter-3/data.js"],"references":[]},{"id":"chapter-3/data.js:h15","chapter":2,"mode":"pathways","topic":"Home care","format":"choice","prompt":"A worker is assigned household management and daily support, with medication-related assistance only when authorized. Which home-care category best fits?","choices":["Home support services","Professional services","Secondary care","Supplementary benefits"],"answer":[0],"explain":"The chapter’s home-support category includes household management and daily support. Follow the care plan, employer policy, training and authorized role for any assigned task.","source":"Chapter 2 textbook, “Home Care Services and Funding”; Therese quiz review","originalId":"h15","group":"Chapter 2","bank":"Chapters 2 & 3","sourceFiles":["chapter-3/data.js"],"references":[]},{"id":"chapter-3/data.js:h16","chapter":2,"mode":"pathways","topic":"Home care","format":"choice","prompt":"Which task is an instrumental activity of daily living (IADL), rather than a basic personal-care ADL?","choices":["Shopping for groceries or managing banking","Bathing","Dressing","Transferring from bed to chair"],"answer":[0],"explain":"Shopping and banking are examples of support for instrumental activities of daily living. A support worker provides these only when assigned and within role expectations.","source":"Chapter 2 textbook, “Home Care Services and Funding”; Therese quiz review","originalId":"h16","group":"Chapter 2","bank":"Chapters 2 & 3","sourceFiles":["chapter-3/data.js"],"references":[]},{"id":"chapter-3/data.js:h17","chapter":2,"mode":"pathways","topic":"Home care","format":"choice","prompt":"Which task is usually provided as a professional home-care service rather than a support-worker personal-care task?","choices":["Physiotherapy","Dressing assistance","Help with shopping","Household cleaning"],"answer":[0],"explain":"Professional services are delivered by the relevant health-care providers and include therapies such as physiotherapy, occupational therapy, speech therapy, nursing and social work.","source":"Chapter 2 textbook, “Home Care Services and Funding”","originalId":"h17","group":"Chapter 2","bank":"Chapters 2 & 3","sourceFiles":["chapter-3/data.js"],"references":[]},{"id":"chapter-3/data.js:h18","chapter":2,"mode":"pathways","topic":"Home care","format":"choice","prompt":"A client moves to another province and expects the same home-care package. Which statement is most accurate?","choices":["Eligibility, funded hours and services may change because provinces and territories set their own home-care programs.","The Canada Health Act guarantees an identical home-care package nationwide.","Only private agencies can provide home care after a move.","Federal tax transfers set each client’s personal care hours directly."],"answer":[0],"explain":"The textbook says the Canada Health Act does not specify a single home-care package. Provinces and territories define their own systems, so funding, eligibility and services vary.","source":"Chapter 2 textbook, “Home Care Services and Funding”; Therese quiz review","originalId":"h18","group":"Chapter 2","bank":"Chapters 2 & 3","sourceFiles":["chapter-3/data.js"],"references":[]},{"id":"chapter-3/data.js:h19","chapter":2,"mode":"pathways","topic":"Home care","format":"choice","prompt":"A client receives publicly funded home support from a local provider. Which statement about providers is accurate?","choices":["Public and private organizations, including for-profit and not-for-profit agencies, may provide services.","Only federal employees can deliver home-care support.","Only hospitals may provide services in a client’s home.","Private agencies are prohibited from providing publicly funded support."],"answer":[0],"explain":"The textbook describes public and private agencies, including for-profit and not-for-profit organizations, as home-care service providers. A public program’s eligibility and funded hours still vary by jurisdiction.","source":"Chapter 2 textbook, “Home Care Services and Funding”","originalId":"h19","group":"Chapter 2","bank":"Chapters 2 & 3","sourceFiles":["chapter-3/data.js"],"references":[]},{"id":"chapter-3/data.js:h20","chapter":2,"mode":"pathways","topic":"Home care","format":"choice","prompt":"A home-care plan assigns personal care and IADL assistance to a support worker. Which action is within that role?","choices":["Provide the assigned support within training, policy and supervision.","Diagnose a new condition and prescribe treatment.","Deliver every nursing and therapy service independently.","Ignore the care plan when a client asks for something different."],"answer":[0],"explain":"The textbook says support workers provide most home-care support services, including personal care, home support and IADL assistance. Follow the assigned plan, training, policy and supervision.","source":"Chapter 2 textbook, “Home Care Services and Funding”; Therese quiz review","originalId":"h20","group":"Chapter 2","bank":"Chapters 2 & 3","sourceFiles":["chapter-3/data.js"],"references":[]},{"id":"chapter-3/data.js:h21","chapter":2,"mode":"pathways","topic":"Home care","format":"choice","prompt":"A screened volunteer delivers meals and makes friendly visits as part of a home-care program. How is this support best classified?","choices":["Volunteer service","Professional therapy","Tertiary care","A Canada Health Act principle"],"answer":[0],"explain":"The chapter distinguishes volunteer services, such as Meals on Wheels or friendly visiting, from professional services and assigned support-worker duties.","source":"Chapter 2 textbook, “Home Care Services and Funding”","originalId":"h21","group":"Chapter 2","bank":"Chapters 2 & 3","sourceFiles":["chapter-3/data.js"],"references":[]},{"id":"chapter-3/data.js:h22","chapter":2,"mode":"pathways","topic":"Health system & coverage","format":"choice","prompt":"Which group consists of supplementary benefits that may be available to some people under particular programs?","choices":["Prescription drugs, dental or vision care, and equipment such as wheelchairs or prostheses","Medically necessary hospital and physician services only","Every private home-care visit for every resident","Only physician services delivered in an emergency department"],"answer":[0],"explain":"Supplementary benefits may include prescription drugs, dental and vision care, medical equipment and appliances, and some additional services. Eligibility and coverage amounts vary; do not assume full coverage.","source":"Chapter 2 textbook, “Additional (Supplementary) Services”; Therese quiz review","originalId":"h22","group":"Chapter 2","bank":"Chapters 2 & 3","sourceFiles":["chapter-3/data.js"],"references":[]},{"id":"chapter-3/data.js:h23","chapter":2,"mode":"pathways","topic":"Health system & coverage","format":"choice","prompt":"A client sees wheelchairs listed among supplementary benefits and assumes every person receives full payment. Which correction is best?","choices":["Eligibility and the amount covered depend on the specific public program or insurance plan.","Every wheelchair is fully paid under the Canada Health Act.","Equipment is covered only by private insurance.","Supplementary benefits cover the same items and amounts for everyone."],"answer":[0],"explain":"Therese warned against assuming “complete coverage.” The textbook says supplementary benefit coverage varies and private-plan coverage also depends on the plan purchased.","source":"Chapter 2 textbook, “Additional (Supplementary) Services” and “Private Health Insurance”; Therese quiz review","originalId":"h23","group":"Chapter 2","bank":"Chapters 2 & 3","sourceFiles":["chapter-3/data.js"],"references":[]},{"id":"chapter-3/data.js:h24","chapter":2,"mode":"pathways","topic":"Health system & coverage","format":"choice","prompt":"An employer offers private insurance. What determines whether a worker’s plan covers prescription drugs, ambulance services or home care?","choices":["The specific plan’s terms, eligibility rules and coverage limits","A standard package identical across all employers","The Canada Health Act’s core hospital-and-physician coverage","The local hospital’s decision about the client’s care level"],"answer":[0],"explain":"Private plans differ by company and by the coverage purchased; the service and amount covered can vary. Supplementary benefits are not a single guaranteed package.","source":"Chapter 2 textbook, “Private Health Insurance”; Therese quiz review","originalId":"h24","group":"Chapter 2","bank":"Chapters 2 & 3","sourceFiles":["chapter-3/data.js"],"references":[]},{"id":"chapter-3/data.js:h25","chapter":2,"mode":"pathways","topic":"Health system & coverage","format":"choice","prompt":"Drug, technology, building and labour expenses are all rising. Which system challenge do these pressures illustrate?","choices":["The steadily rising cost of care","The growth of appropriate outpatient day surgery","The existence of community clinics","The use of telehealth"],"answer":[0],"explain":"The textbook identifies rising costs as the greatest challenge, noting the expense of drugs, technology, buildings and labour. Therese also highlighted cost pressures during class review.","source":"Chapter 2 textbook, “Health Care Challenges, Supplementary Services, and Trends”; Therese quiz review","originalId":"h25","group":"Chapter 2","bank":"Chapters 2 & 3","sourceFiles":["chapter-3/data.js"],"references":[]},{"id":"chapter-3/data.js:h26","chapter":2,"mode":"pathways","topic":"Health system & coverage","format":"choice","prompt":"Which combination best reflects current pressures on Canada’s health-care system?","choices":["Worker shortages, aging populations and workforce, rising costs, and waits for care","More rural health workers, lower costs and shorter waits","Fewer people needing care and identical eligibility rules everywhere","An increase in home care that eliminates hospital demand"],"answer":[0],"explain":"The chapter discusses health-worker shortages, population and workforce aging, waiting lists, LTC admission waits and rising costs as pressures on the system.","source":"Chapter 2 textbook, “Health Care Challenges, Supplementary Services, and Trends”; Chapter 2 slides 17","originalId":"h26","group":"Chapter 2","bank":"Chapters 2 & 3","sourceFiles":["chapter-3/data.js"],"references":[]},{"id":"chapter-3/data.js:h27","chapter":2,"mode":"pathways","topic":"Health system & coverage","format":"choice","prompt":"Why have outpatient day surgery and home- or community-based services become more common?","choices":["They can provide suitable care outside hospital and reduce avoidable spending or pressure.","They remove the need for assessment and follow-up.","They make every service publicly funded for every resident.","They move all tertiary procedures into clients’ homes."],"answer":[0],"explain":"The chapter describes alternatives such as clinics, health centres, day surgery and home care as ways to provide quality care while avoiding needless spending. Suitability depends on the client and service.","source":"Chapter 2 textbook, “Health Care Trends”; Therese quiz review","originalId":"h27","group":"Chapter 2","bank":"Chapters 2 & 3","sourceFiles":["chapter-3/data.js"],"references":[]},{"id":"chapter-3/data.js:h28","chapter":2,"mode":"pathways","topic":"Health system & coverage","format":"choice","prompt":"Which option is an alternative health practice rather than a care level or insurance program?","choices":["Acupuncture","Tertiary care","A provincial health-insurance plan","A specialist referral"],"answer":[0],"explain":"The chapter lists practices such as massage therapies, homeopathy, herbal medicines and acupuncture. It treats these separately from the three levels of health-care delivery.","source":"Chapter 2 textbook, “Alternative Health Practices”","originalId":"h28","group":"Chapter 2","bank":"Chapters 2 & 3","sourceFiles":["chapter-3/data.js"],"references":[]},{"id":"chapter-3/data.js:c11","chapter":3,"mode":"setting","topic":"Workplace settings","format":"scenario","prompt":"An older adult with early-stage Alzheimer’s is unsafe alone during the day while their daughter works. Which service can offer supervised daytime activities and caregiver support while the client continues living at home?","choices":["An adult day program","Long-term care placement without a needs assessment","An inpatient hospital admission for each workday","A private insurance plan"],"answer":[0],"explain":"Therese highlighted adult day programs as daytime supervision, activity and caregiver support that can help someone remain in the community when appropriate. Early dementia alone does not automatically mean long-term care.","source":"Therese Chapter 3 quiz review; Workplace Setting slides 14–15","originalId":"c11","group":"Chapter 3","bank":"Chapters 2 & 3","sourceFiles":["chapter-3/data.js"],"references":[]},{"id":"chapter-3/data.js:c12","chapter":3,"mode":"acuity","topic":"Care types","format":"scenario","prompt":"A person is experiencing harms related to illicit drug use and needs help with addiction. Which service is most directly focused on these needs while the team assesses appropriate ongoing supports?","choices":["Specialized mental-health and addiction services","Long-term care, based on the diagnosis alone","Retirement-home housekeeping","Routine acute care as the only continuing service"],"answer":[0],"explain":"Therese emphasized matching the service to the need and stabilizing the client through specialized mental-health or addiction services before choosing a longer-term living arrangement.","source":"Therese Chapter 3 quiz review","originalId":"c12","group":"Chapter 3","bank":"Chapters 2 & 3","sourceFiles":["chapter-3/data.js"],"references":[]},{"id":"chapter-3/data.js:c13","chapter":3,"mode":"safety","topic":"Benefits & challenges","format":"choice","prompt":"A resident in long-term care pays a monthly fee. Which statement best describes how public Medicare coverage may contribute to the cost?","choices":["Medicare covers some costs, while the resident may pay a monthly fee toward the balance.","Medicare covers every cost, so a monthly fee is never charged.","The resident pays the entire cost because no public funding applies.","Only private insurance can contribute to long-term-care costs."],"answer":[0],"explain":"Public funding covers some long-term-care costs, while residents may pay a monthly fee toward the balance. Coverage and fees depend on the relevant program and setting.","source":"Workplace Setting slide 19; Therese Chapter 3 quiz review","originalId":"c13","group":"Chapter 3","bank":"Chapters 2 & 3","sourceFiles":["chapter-3/data.js"],"references":[]},{"id":"chapter-3/data.js:c14","chapter":3,"mode":"setting","topic":"Workplace settings","format":"choice","prompt":"An independently mobile older adult lives in a residence with their own bedroom and bathroom, shared dining and living areas, and housekeeping help. They need little personal care; if their daily care needs grow beyond minimal support, a move may be needed. Which residence is described?","choices":["Retirement residence","Long-term care facility","Community day program","Acute-care hospital"],"answer":[0],"explain":"A retirement residence supports older adults who are largely independent, with accommodation, security, hospitality services, and limited personal care. The text also notes that a retirement home is one type of assisted-living facility, so those labels can overlap; higher daily nursing and personal-care needs point toward long-term care.","source":"Chapter 3, “Retirement Residences” (pp. 38–39)","originalId":"c14","group":"Chapter 3","bank":"Chapters 2 & 3","sourceFiles":["chapter-3/data.js"],"references":[]},{"id":"chapter-3/data.js:c15","chapter":3,"mode":"setting","topic":"Workplace settings","format":"choice","prompt":"A hospital patient is assigned a bed and stays overnight for observation. Which term describes the patient’s status?","choices":["Inpatient","Outpatient","Resident","Day-program participant"],"answer":[0],"explain":"An inpatient is assigned a bed and admitted to stay overnight or longer. An outpatient receives care without staying overnight. The distinction is about the patient’s admission and stay, not whether the procedure is complex.","source":"Chapter 3, “Working in Facility-Based Settings” (p. 42)","originalId":"c15","group":"Chapter 3","bank":"Chapters 2 & 3","sourceFiles":["chapter-3/data.js"],"references":[]},{"id":"chapter-3/data.js:c16","chapter":3,"mode":"care","topic":"Care types","format":"choice","prompt":"A terminally ill client is no longer seeking life-prolonging treatment. The support worker provides ADL assistance and encouragement while respecting the client’s emotional, social, and spiritual needs. Which care type is the clearest match?","choices":["Hospice care","Subacute care","Respite care","Long-term care"],"answer":[0],"explain":"Hospice is for a client with a terminal diagnosis who is no longer seeking life-prolonging care. Support workers may assist with personal care and ADLs and offer emotional support to the client and family.","source":"Chapter 3, “Workplace Settings and Services Provided” (p. 37)","originalId":"c16","group":"Chapter 3","bank":"Chapters 2 & 3","sourceFiles":["chapter-3/data.js"],"references":[]},{"id":"chapter-3/data.js:c17","chapter":3,"mode":"setting","topic":"Workplace settings","format":"scenario","prompt":"An older resident lives in their own apartment with a kitchen and needs support with some ADLs. The residence offers emergency response, social programs, meals, housekeeping, and laundry; services can vary by resident. Which setting best fits?","choices":["Assisted-living (supportive housing) facility","Long-term care facility","Hospital inpatient unit","Community day program"],"answer":[0],"explain":"Assisted-living facilities provide apartments and support services, commonly including 24-hour supervision and emergency response, recreation, meals, housekeeping, and laundry. Some residents buy extra help or qualify for home care. A retirement home is one type of assisted-living facility.","source":"Chapter 3, “Assisted-Living Facilities” (p. 39)","originalId":"c17","group":"Chapter 3","bank":"Chapters 2 & 3","sourceFiles":["chapter-3/data.js"],"references":[]},{"id":"chapter-3/data.js:c18","chapter":3,"mode":"setting","topic":"Workplace settings","format":"scenario","prompt":"A resident in an assisted-living apartment now needs extensive personal care and 24-hour professional nursing. Which setting is designed for that higher level of ongoing care when hospital treatment is not needed?","choices":["Long-term care facility","Retirement residence with hospitality services only","Community day program","Acute-care hospital"],"answer":[0],"explain":"Long-term care facilities provide accommodation, 24-hour professional nursing, and support to people who cannot care for themselves at home but do not need hospital care. They offer a higher level of care than retirement residences and assisted-living facilities.","source":"Chapter 3, “Long-Term Care Facilities” (p. 42)","originalId":"c18","group":"Chapter 3","bank":"Chapters 2 & 3","sourceFiles":["chapter-3/data.js"],"references":[]},{"id":"chapter-3/data.js:c19","chapter":3,"mode":"safety","topic":"Safety & role","format":"scenario","prompt":"During home care, a client’s physiotherapist asks you to add an unfamiliar exercise to the shift. Your agency supervisor has not assigned it, and you are unsure whether policy permits it. What should you do?","choices":["Check with your supervisor before doing the unfamiliar or unapproved task.","Do it because the request came from a regulated health professional.","Try it once and report afterward if the client tolerates it.","Ask the client’s family to authorize it instead of checking agency policy."],"answer":[0],"explain":"When different providers give direction, check with the supervisor before performing a task that is unfamiliar or not allowed by agency policy. Stay within your training, job description, and scope.","source":"Chapter 3, “Benefits and Challenges Associated With Working in Home Care” (p. 40)","originalId":"c19","group":"Chapter 3","bank":"Chapters 2 & 3","sourceFiles":["chapter-3/data.js"],"references":[]},{"id":"chapter-3/data.js:c20","chapter":3,"mode":"safety","topic":"Safety & role","format":"scenario","prompt":"During a home visit, you notice a frayed electrical cord beside a client who smokes. The care task itself is going smoothly. What is the best next step?","choices":["Discuss the safety concern with the client and your supervisor.","Ignore it because the cord is outside the current care task.","Repair the electrical cord yourself before continuing.","Ask the client to promise not to use the cord and make no report."],"answer":[0],"explain":"The chapter identifies frayed cords and unsafe smoking practices as possible hazards in clients’ homes. Discuss safety concerns with the client and supervisor; do not take on repair work beyond your role.","source":"Chapter 3, “Benefits and Challenges Associated With Working in Home Care” (p. 40)","originalId":"c20","group":"Chapter 3","bank":"Chapters 2 & 3","sourceFiles":["chapter-3/data.js"],"references":[]},{"id":"chapter-3/data.js:c21","chapter":3,"mode":"setting","topic":"Workplace settings","format":"scenario","prompt":"A day program for adults with health conditions runs in a room inside a nursing home. Participants attend for structured activities and personal assistance, then return to their homes. Which conclusion is best?","choices":["It is a community day program; the building hosting it does not change the program’s daytime purpose.","It is long-term care because every service in a nursing home is residential care.","It is inpatient care because the host building also has inpatient beds.","It is respite care only if every participant has a family caregiver."],"answer":[0],"explain":"Community day programs may be held in hospitals, nursing homes, community centres, churches, or other sites. They provide daytime services to participants who live in the community and may also provide a break for family caregivers.","source":"Chapter 3, “Community Day Programs” (p. 41)","originalId":"c21","group":"Chapter 3","bank":"Chapters 2 & 3","sourceFiles":["chapter-3/data.js"],"references":[]},{"id":"chapter-3/data.js:c22","chapter":3,"mode":"safety","topic":"Benefits & challenges","format":"scenario","prompt":"At a community day program, several participants need attention at once. One asks for help with personal care while others are waiting for an activity to begin. Which skill set most directly addresses this challenge?","choices":["Prioritize needs using sound judgment and time management while focusing on each person.","Complete tasks in arrival order, regardless of urgency or individual need.","Leave the group to ask family caregivers to decide which participant goes first.","Promise immediate attention to everyone before checking what is possible."],"answer":[0],"explain":"Day-program staff may need to attend to many people, focus on each person, and decide whose needs to address first. Judgment and time management are essential.","source":"Chapter 3, “Benefits and Challenges Associated With Working in a Community Day Program” (p. 41)","originalId":"c22","group":"Chapter 3","bank":"Chapters 2 & 3","sourceFiles":["chapter-3/data.js"],"references":[]},{"id":"chapter-3/data.js:c23","chapter":3,"mode":"safety","topic":"Safety & role","format":"scenario","prompt":"A hospital nurse asks a support worker to perform a procedure the worker has never been taught. The client is stable, and the nurse is busy. What is the appropriate response?","choices":["Do not attempt it; explain the training gap and follow facility policy for obtaining direction.","Perform it because the nurse requested it and the client is stable.","Ask an experienced support worker to demonstrate once, then proceed alone.","Wait until after the procedure, then document that it was unfamiliar."],"answer":[0],"explain":"Facility policy, training, and supervision govern delegated tasks. Never perform a procedure you have not been taught or cannot do safely, even when asked by a nurse.","source":"Chapter 3, “Hospitals and Other Facility-Based Care” and “Benefits and Challenges Associated With Working in a Facility” (pp. 42–43)","originalId":"c23","group":"Chapter 3","bank":"Chapters 2 & 3","sourceFiles":["chapter-3/data.js"],"references":[]},{"id":"chapter-3/data.js:c24","chapter":3,"mode":"safety","topic":"Workplace settings","format":"scenario","prompt":"A long-term-care resident has a gradual change in daily function. Which contribution is within a support worker’s team role?","choices":["Report observations to the nurse and contribute relevant information to the care plan or family conference.","Diagnose the cause and revise the resident’s nursing plan independently.","Wait to mention it until the next formal assessment, even if it affects care today.","Tell the family a diagnosis so they can change the care plan."],"answer":[0],"explain":"Support workers report to a nurse, provide personal care, and contribute valuable observations to care plans and family conferences. Nurses plan and coordinate resident care.","source":"Chapter 3, “Long-Term Care Facilities” (p. 42)","originalId":"c24","group":"Chapter 3","bank":"Chapters 2 & 3","sourceFiles":["chapter-3/data.js"],"references":[]},{"id":"chapter-3/data.js:c25","chapter":3,"mode":"care","topic":"Care types","format":"scenario","prompt":"A client is medically stable after an injury but cannot yet return home because they still need inpatient care with complex equipment and frequent treatment. Which distinction is most accurate?","choices":["This can be subacute/complex continuing care even though the client is stable.","It must be long-term care because the client is not going home today.","It is outpatient care because the client is recovering rather than acutely ill.","It is restorative care only, which excludes inpatient treatment."],"answer":[0],"explain":"Subacute or complex continuing care serves people who are recovering from surgery, injury, acute illness, or an exacerbation. A stable client may still need complex procedures and inpatient recovery before discharge.","source":"Chapter 3, “Workplace Settings and Services Provided” (p. 36)","originalId":"c25","group":"Chapter 3","bank":"Chapters 2 & 3","sourceFiles":["chapter-3/data.js"],"references":[]},{"id":"chapter-3/data.js:c26","chapter":3,"mode":"setting","topic":"Workplace settings","format":"choice","prompt":"A small shared house in a neighbourhood provides residents with disabilities 24-hour supervision, meals, housekeeping, laundry, and help with personal care and ADLs. Which setting is described?","choices":["Group home","Retirement residence","Hospital outpatient clinic","Community day program"],"answer":[0],"explain":"A group home is a live-in facility where a small number of people with physical or mental disabilities live together and receive supervision, care, and support. Residents generally share living and dining spaces.","source":"Chapter 3, “Group Homes” (p. 40)","originalId":"c26","group":"Chapter 3","bank":"Chapters 2 & 3","sourceFiles":["chapter-3/data.js"],"references":[]},{"id":"chapter-3/data.js:c27","chapter":3,"mode":"care","topic":"Care types","format":"choice","prompt":"A person’s mental-health assessment and treatment plan is designed to help them function as independently as possible after returning to community life. Which statement best fits the service model?","choices":["Mental-health services may be inpatient or outpatient and often aim to support a return to community living.","Mental-health services require long-term hospital admission in every case.","Community support begins only after all treatment has stopped.","A return to the community means the person no longer needs health services."],"answer":[0],"explain":"Mental-health services include both inpatient and outpatient care. Clients are usually encouraged to return to the community, where community-based care and support can help them function independently.","source":"Chapter 3, “Workplace Settings and Services Provided” (p. 37)","originalId":"c27","group":"Chapter 3","bank":"Chapters 2 & 3","sourceFiles":["chapter-3/data.js"],"references":[]},{"id":"chapter-3/data.js:c28","chapter":3,"mode":"setting","topic":"Workplace settings","format":"scenario","prompt":"A First Nation employs a support worker in a rural community. The job description emphasizes home management as well as personal care, unlike a nearby agency’s role. Which conclusion follows from the chapter?","choices":["The role may vary by employer; read the specific job description and stay within that scope.","The role is invalid because support workers everywhere must have identical duties.","The worker may take on any task that improves community access.","Only personal care can be included in Indigenous or First Nations services."],"answer":[0],"explain":"Indigenous or First Nations services aim to support and empower Indigenous peoples to improve access to and delivery of services. Support-worker job descriptions may vary between employers, so follow the local role and scope.","source":"Chapter 3, “Workplace Settings and Services Provided” (p. 36)","originalId":"c28","group":"Chapter 3","bank":"Chapters 2 & 3","sourceFiles":["chapter-3/data.js"],"references":[]},{"id":"chapter-3/data.js:c29","chapter":3,"mode":"safety","topic":"Benefits & challenges","format":"scenario","prompt":"You are hired directly by a client. The client’s requested tasks and weekly hours have changed several times, and no written expectations were agreed. What should you clarify first?","choices":["The expected duties, how performance will be assessed, and the employment terms such as hours and pay.","Whether the client will let you skip the provincial scope of practice.","Whether family members can approve nursing procedures on the client’s behalf.","Whether you can delay clarifying duties until a problem occurs."],"answer":[0],"explain":"For direct employment, clarify work limits and performance expectations before starting, preferably in writing. Hours and pay may change from week to week, so understand the terms before agreeing.","source":"Chapter 3, “Working Directly for Clients” and “Benefits and Challenges Associated With Working Directly for Clients” (p. 42)","originalId":"c29","group":"Chapter 3","bank":"Chapters 2 & 3","sourceFiles":["chapter-3/data.js"],"references":[]},{"id":"chapter-3/data.js:c30","chapter":3,"mode":"safety","topic":"Benefits & challenges","format":"scenario","prompt":"A support worker is self-employed and provides care in a client’s home. Which risk-management point is singled out for this arrangement?","choices":["The worker is legally responsible for workplace injuries or mishaps and should carry liability insurance.","The client’s public funding automatically covers the worker’s liability.","The agency’s insurance always covers a self-employed worker.","The worker’s only responsibility is to record hours and pay."],"answer":[0],"explain":"The chapter says self-employed support workers are legally responsible for injury or workplace mishaps that occur while providing care and identifies liability insurance as important.","source":"Chapter 3, “Benefits and Challenges Associated With Working Directly for Clients” (p. 42)","originalId":"c30","group":"Chapter 3","bank":"Chapters 2 & 3","sourceFiles":["chapter-3/data.js"],"references":[]},{"id":"chapter-3/data.js:c31","chapter":3,"mode":"safety","topic":"Benefits & challenges","format":"choice","prompt":"Which feature is described as a possible benefit of home-care work, even though it can also require independent judgment?","choices":["Working one-on-one and having independence to solve some problems","Having nurses and other professionals physically present at all times","Following the same routine for every client","Avoiding all scheduling around a client’s care needs"],"answer":[0],"explain":"Some workers value one-on-one variety and the independence of home care. A supervisor may be reachable by phone, so the worker may need judgment to solve problems within their role.","source":"Chapter 3, “Benefits and Challenges Associated With Working in Home Care” (p. 40)","originalId":"c31","group":"Chapter 3","bank":"Chapters 2 & 3","sourceFiles":["chapter-3/data.js"],"references":[]},{"id":"chapter-3/data.js:c32","chapter":3,"mode":"safety","topic":"Benefits & challenges","format":"scenario","prompt":"In a live-in facility, a worker begins personal care without knocking because the task is behind schedule. Which action best protects the resident’s privacy and dignity?","choices":["Knock and announce yourself, screen the area, cover the resident, and respect their preferences.","Finish quickly because timeliness is more important than privacy during personal care.","Ask another resident to close the door while you begin.","Discuss the resident’s care in a common area so the team is informed."],"answer":[0],"explain":"The chapter emphasizes treating a live-in facility as the resident’s home. Knock and announce your presence, provide privacy during care, keep client discussions confidential and professional, and respect preferences and property.","source":"Chapter 3, “Especially in Live-in Facilities” (p. 43)","originalId":"c32","group":"Chapter 3","bank":"Chapters 2 & 3","sourceFiles":["chapter-3/data.js"],"references":[]},{"id":"chapter-3/data.js:c33","chapter":3,"mode":"safety","topic":"Benefits & challenges","format":"choice","prompt":"A facility uses evening and night shifts, sometimes lasting 8 to 12 hours. Which statement best reflects the chapter’s discussion of shift work?","choices":["It is a workplace challenge for some workers, though others value the variety or scheduling flexibility.","It is always a benefit because the facility is open all day.","It is a safety procedure reserved for long-term care residents.","It means a worker may skip required handover and care plans."],"answer":[0],"explain":"Facilities operate throughout the day. Some workers enjoy different shifts or the schedule they create, while others struggle with changes to sleep and lifestyle.","source":"Chapter 3, “Benefits and Challenges Associated With Working in a Facility” (p. 43)","originalId":"c33","group":"Chapter 3","bank":"Chapters 2 & 3","sourceFiles":["chapter-3/data.js"],"references":[]},{"id":"chapter-3/data.js:c34","chapter":3,"mode":"setting","topic":"Workplace settings","format":"choice","prompt":"An older person can manage personal care but wants accommodation, meals, housekeeping, and security. They do not need ongoing nursing. Which residence is the closest match?","choices":["Retirement residence","Long-term care facility","Inpatient hospital unit","Group home providing 24-hour personal-care support"],"answer":[0],"explain":"Retirement residences support older adults who are independently mobile and need little or no personal-care assistance. People who need more than minimal daily care may need long-term care instead.","source":"Chapter 3, “Retirement Residences” (pp. 38–39)","originalId":"c34","group":"Chapter 3","bank":"Chapters 2 & 3","sourceFiles":["chapter-3/data.js"],"references":[]},{"id":"chapter-4-5/data.js:e01","mode":"terms","topic":"Ethics & terminology","prompt":"A support worker uses shared standards of conduct to decide what is right or wrong in a care situation. Which term best describes these guiding rules?","choices":["Ethics","Values","Belief","Conduct"],"answer":[0],"explain":"Ethics are rules of conduct that guide decisions about right and wrong, and good and bad.","source":"Ethics slides, “Ethics”; Chapter 4, “The Influence of Culture…”","originalId":"e01","group":"Chapter 4","bank":"Chapters 4, 5 & 10","sourceFiles":["chapter-4-5/data.js","chapter-4-5/chapter4_focus.js","chapter-4-5/chapter10.js","chapter-4-5/post_ch5_review.js","chapter-4-5/challenge_rounds.js"],"references":[]},{"id":"chapter-4-5/data.js:e02","mode":"terms","topic":"Ethics & terminology","prompt":"A client says, “I believe family decisions should be made together.” Which interpretation best identifies the belief rather than a law, value judgment or action?","choices":["A conviction the client holds to be true.","A rule that legally requires relatives to decide.","The client’s relative ranking of all personal qualities.","The observable act of obtaining family consent."],"answer":[0],"explain":"A belief is a conviction held to be true. It does not itself establish legal authority, describe every value, or demonstrate an action.","source":"Ethics slides, “Ethics”; Chapter 4, Key Terms","originalId":"e02","group":"Chapter 4","bank":"Chapters 4, 5 & 10","sourceFiles":["chapter-4-5/data.js","chapter-4-5/chapter4_focus.js","chapter-4-5/chapter10.js","chapter-4-5/post_ch5_review.js","chapter-4-5/challenge_rounds.js"],"references":[]},{"id":"chapter-4-5/data.js:e03","mode":"terms","topic":"Ethics & terminology","prompt":"A worker regards compassion and honesty as especially worthwhile qualities in a person. These are the worker’s:","choices":["Values","Regulations","Torts","Rights"],"answer":[0],"explain":"Values are qualities an individual considers worthwhile or desirable in a person.","source":"Ethics slides, “Ethics”; Chapter 4, Key Terms","originalId":"e03","group":"Chapter 4","bank":"Chapters 4, 5 & 10","sourceFiles":["chapter-4-5/data.js","chapter-4-5/chapter4_focus.js","chapter-4-5/chapter10.js","chapter-4-5/post_ch5_review.js","chapter-4-5/challenge_rounds.js"],"references":[]},{"id":"chapter-4-5/data.js:e04","mode":"terms","topic":"Ethics & terminology","prompt":"Which statement best distinguishes morals from ethics?","choices":["Morals are principles a person believes are right or wrong for themselves; ethics are rules of conduct guiding right and wrong.","Morals are legal rules; ethics are personal preferences.","Morals refer only to sexual behaviour; ethics refer only to work.","There is no distinction; the words mean exactly the same thing."],"answer":[0],"explain":"The terms are often confused, but the text distinguishes personal principles of right and wrong (morals) from conduct-guiding rules (ethics). Neither term is limited to sexuality or the workplace.","source":"Ethics slides, “Ethics cont.”; Chapter 4, Key Terms","originalId":"e04","group":"Chapter 4","bank":"Chapters 4, 5 & 10","sourceFiles":["chapter-4-5/data.js","chapter-4-5/chapter4_focus.js","chapter-4-5/chapter10.js","chapter-4-5/post_ch5_review.js","chapter-4-5/challenge_rounds.js"],"references":[]},{"id":"chapter-4-5/data.js:e05","mode":"terms","topic":"Ethics & terminology","prompt":"A care situation presents two opposing moral choices, and choosing either one means going against the other. This is an:","choices":["Ethical dilemma","Informed consent","Act","Oath of confidentiality"],"answer":[0],"explain":"An ethical dilemma involves an apparent conflict between opposing moral choices.","source":"Ethics slides, “Principles of Healthcare Ethics”; Chapter 4, Key Terms","originalId":"e05","group":"Chapter 4","bank":"Chapters 4, 5 & 10","sourceFiles":["chapter-4-5/data.js","chapter-4-5/chapter4_focus.js","chapter-4-5/chapter10.js","chapter-4-5/post_ch5_review.js","chapter-4-5/challenge_rounds.js"],"references":[]},{"id":"chapter-4-5/data.js:e06","mode":"terms","topic":"Ethics & terminology","prompt":"An HCA finds that a code of ethics supports more than one possible response to a conflict. What should the worker conclude?","choices":["The code guides judgment, but facts, consequences and appropriate consultation still matter.","An unresolved conflict means the code no longer applies.","The worker can select the preferred option without further fact-finding.","A code supplies a unique answer once the worker finds the correct heading."],"answer":[0],"explain":"A code provides ethical guidance rather than a complete automatic answer for every situation.","source":"Ethics slides, “Code of Ethics” and “Ethical Dilemmas”; Chapter 4, “Dealing With Ethical Dilemmas”","originalId":"e06","group":"Chapter 4","bank":"Chapters 4, 5 & 10","sourceFiles":["chapter-4-5/data.js","chapter-4-5/chapter4_focus.js","chapter-4-5/chapter10.js","chapter-4-5/post_ch5_review.js","chapter-4-5/challenge_rounds.js"],"references":[]},{"id":"chapter-4-5/data.js:p01","mode":"principles","topic":"Four principles","prompt":"A mentally competent client refuses to use a cane, even though the worker thinks it would be safer. Which principle most directly supports respecting the client’s decision?","choices":["Autonomy","Justice","Beneficence","Nonmaleficence"],"answer":[0],"explain":"Autonomy, also called self-determination, is the freedom and choice to make decisions that affect one’s life. Respect the decision without judgment and raise safety concerns with the supervisor.","source":"Ethics slides, “Autonomy”; Chapter 4, “Autonomy”","originalId":"p01","group":"Chapter 4","bank":"Chapters 4, 5 & 10","sourceFiles":["chapter-4-5/data.js","chapter-4-5/chapter4_focus.js","chapter-4-5/chapter10.js","chapter-4-5/post_ch5_review.js","chapter-4-5/challenge_rounds.js"],"references":[]},{"id":"chapter-4-5/data.js:p02","mode":"principles","topic":"Four principles","prompt":"A demanding client is less pleasant than others. The worker provides the same attentive care rather than shortening this client’s visits. Which principle is demonstrated?","choices":["Justice","Autonomy","Beneficence","Nonmaleficence"],"answer":[0],"explain":"Justice means fair and equal treatment. A client’s temperament or lifestyle should not determine whether the worker gives them appropriate attention and care.","source":"Ethics slides, “Justice”; Chapter 4, “Justice”","originalId":"p02","group":"Chapter 4","bank":"Chapters 4, 5 & 10","sourceFiles":["chapter-4-5/data.js","chapter-4-5/chapter4_focus.js","chapter-4-5/chapter10.js","chapter-4-5/post_ch5_review.js","chapter-4-5/challenge_rounds.js"],"references":[]},{"id":"chapter-4-5/data.js:p03","mode":"principles","topic":"Four principles","prompt":"A family member asks a worker to skip a client’s planned bath so the worker can finish early. The worker focuses on the client’s need and calls the supervisor for guidance. Which principle is most central?","choices":["Beneficence","Justice","Autonomy","Nonmaleficence"],"answer":[0],"explain":"Beneficence means doing or promoting good. The client’s needs come before the family’s convenience; contacting the supervisor is appropriate when a request conflicts with those needs.","source":"Ethics slides, “Beneficence”; Chapter 4, “Beneficence”","originalId":"p03","group":"Chapter 4","bank":"Chapters 4, 5 & 10","sourceFiles":["chapter-4-5/data.js","chapter-4-5/chapter4_focus.js","chapter-4-5/chapter10.js","chapter-4-5/post_ch5_review.js","chapter-4-5/challenge_rounds.js"],"references":[]},{"id":"chapter-4-5/data.js:p04","mode":"principles","topic":"Four principles","prompt":"A client asks a worker to perform a care procedure the worker has not been trained to do. The worker declines and contacts the supervisor. Which principle most directly explains this response?","choices":["Nonmaleficence","Justice","Autonomy","Beneficence"],"answer":[0],"explain":"Nonmaleficence means doing no harm. Taking on a task without the required training can place the client at risk, even when the worker intends to help.","source":"Ethics slides, “Nonmaleficence”; Chapter 4, “Nonmaleficence”","originalId":"p04","group":"Chapter 4","bank":"Chapters 4, 5 & 10","sourceFiles":["chapter-4-5/data.js","chapter-4-5/chapter4_focus.js","chapter-4-5/chapter10.js","chapter-4-5/post_ch5_review.js","chapter-4-5/challenge_rounds.js"],"references":[]},{"id":"chapter-4-5/data.js:p05","mode":"principles","topic":"Four principles","prompt":"A client chooses a lifestyle that conflicts with the worker’s personal beliefs. What is the best ethical approach?","choices":["Set aside personal bias and respect the client’s choices without expressing disapproval.","Persuade the client to adopt the worker’s values.","Ask the family to override the client’s choice.","Provide less care until the client changes."],"answer":[0],"explain":"Respecting autonomy includes not judging a client’s choices or lifestyle. The worker should avoid imposing personal beliefs or advice.","source":"Ethics slides, “Autonomy”; Chapter 4, “Autonomy”","originalId":"p05","group":"Chapter 4","bank":"Chapters 4, 5 & 10","sourceFiles":["chapter-4-5/data.js","chapter-4-5/chapter4_focus.js","chapter-4-5/chapter10.js","chapter-4-5/post_ch5_review.js","chapter-4-5/challenge_rounds.js"],"references":[]},{"id":"chapter-4-5/data.js:p06","mode":"principles","topic":"Four principles","prompt":"Which set correctly names the four basic principles of health care ethics?","choices":["Autonomy, justice, beneficence and nonmaleficence","Privacy, consent, dignity and safety","Belief, values, morals and conduct","Negligence, assault, battery and defamation"],"answer":[0],"explain":"The four principles are autonomy (choice), justice (fairness), beneficence (doing good) and nonmaleficence (doing no harm).","source":"Ethics slides, “Principles of Healthcare Ethics”; Chapter 4, “The Principles of Health Care Ethics”","originalId":"p06","group":"Chapter 4","bank":"Chapters 4, 5 & 10","sourceFiles":["chapter-4-5/data.js","chapter-4-5/chapter4_focus.js","chapter-4-5/chapter10.js","chapter-4-5/post_ch5_review.js","chapter-4-5/challenge_rounds.js"],"references":[]},{"id":"chapter-4-5/data.js:p07","mode":"principles","topic":"Four principles","prompt":"A client’s family asks for details about a diagnosis. The worker avoids guessing or sharing medical information and directs them to the supervisor. Which principle is most directly reflected?","choices":["Nonmaleficence","Justice","Autonomy","Beneficence"],"answer":[0],"explain":"Giving medical information outside the worker’s role can be inaccurate and cause harm or distress. Refer diagnosis and treatment questions to the supervisor.","source":"Ethics slides, “Nonmaleficence”; Chapter 4, “Nonmaleficence”","originalId":"p07","group":"Chapter 4","bank":"Chapters 4, 5 & 10","sourceFiles":["chapter-4-5/data.js","chapter-4-5/chapter4_focus.js","chapter-4-5/chapter10.js","chapter-4-5/post_ch5_review.js","chapter-4-5/challenge_rounds.js"],"references":[]},{"id":"chapter-4-5/data.js:p08","mode":"principles","topic":"Four principles","prompt":"Which approach best combines the four principles when a client’s choice worries the care team?","choices":["Learn the client’s wishes, consider fairness and possible benefits, identify risks, and consult the supervisor.","Choose whatever is quickest and ask the client afterward.","Let the family decide because they know the client best.","Ignore the concern so the client’s autonomy is never questioned."],"answer":[0],"explain":"Ethical reasoning considers autonomy, justice, beneficence and nonmaleficence together. Collect information, consider options and consequences, and seek supervisory guidance when needed.","source":"Ethics slides, “Questions to Ask Yourself…”; Chapter 4, “Dealing With Ethical Dilemmas”","originalId":"p08","group":"Chapter 4","bank":"Chapters 4, 5 & 10","sourceFiles":["chapter-4-5/data.js","chapter-4-5/chapter4_focus.js","chapter-4-5/chapter10.js","chapter-4-5/post_ch5_review.js","chapter-4-5/challenge_rounds.js"],"references":[]},{"id":"chapter-4-5/data.js:d01","mode":"dilemmas","topic":"Ethical dilemmas","prompt":"A resident says a family member brought alcohol into the facility and asks the worker to keep it secret. Facility rules prohibit alcohol, and it may interact with medication. What is the best response?","choices":["Explain the safety concern and report it to the supervisor, following policy.","Promise secrecy because autonomy always overrides safety.","Confiscate the alcohol and punish the resident.","Tell other residents so they can help monitor the client."],"answer":[0],"explain":"This dilemma involves the resident’s wishes, potential harm, facility rules and the worker’s responsibilities. Discuss the concern respectfully and inform the supervisor; do not promise secrecy or share broadly.","source":"Ethics slides, “Ethical Dilemmas”; Chapter 4, Box 4.2, Scenario 2","originalId":"d01","group":"Chapter 4","bank":"Chapters 4, 5 & 10","sourceFiles":["chapter-4-5/data.js","chapter-4-5/chapter4_focus.js","chapter-4-5/chapter10.js","chapter-4-5/post_ch5_review.js","chapter-4-5/challenge_rounds.js"],"references":[]},{"id":"chapter-4-5/data.js:d02","mode":"dilemmas","topic":"Ethical dilemmas","prompt":"A parent asks a worker caring for a toddler to leave him alone in his room for 15 minutes or longer after a tantrum. The worker is unsure whether this is safe. What should the worker do?","choices":["Discuss the concern with the supervisor before proceeding.","Follow the instruction without considering possible harm.","Argue with the parent and make a new discipline plan.","Leave the child alone until the parent returns."],"answer":[0],"explain":"The situation raises competing concerns: the parent’s decision-making, fairness to the child, potential benefit, and possible harm. The text specifically recommends discussing the safety concern with the supervisor.","source":"Ethics slides, four principles; Chapter 4, Box 4.2, Scenario 1","originalId":"d02","group":"Chapter 4","bank":"Chapters 4, 5 & 10","sourceFiles":["chapter-4-5/data.js","chapter-4-5/chapter4_focus.js","chapter-4-5/chapter10.js","chapter-4-5/post_ch5_review.js","chapter-4-5/challenge_rounds.js"],"references":[]},{"id":"chapter-4-5/data.js:d03","mode":"dilemmas","topic":"Ethical dilemmas","prompt":"A client becomes incontinent during a public card game. A student worker is told to check who needs help. What is the most respectful first approach?","choices":["Approach discreetly and offer private assistance without identifying the client publicly.","Ask the whole table who needs a change.","Wait until other clients leave, even if the client is uncomfortable.","Tell the group what the worker has noticed."],"answer":[0],"explain":"The worker should preserve privacy and dignity. A discreet, private offer avoids unnecessary embarrassment while still addressing the client’s care needs.","source":"Ethics slides, “Dignity and Respect”; Chapter 4, “Supporting Mrs. Glass: Recognizing the Need for Discretion”","originalId":"d03","group":"Chapter 4","bank":"Chapters 4, 5 & 10","sourceFiles":["chapter-4-5/data.js","chapter-4-5/chapter4_focus.js","chapter-4-5/chapter10.js","chapter-4-5/post_ch5_review.js","chapter-4-5/challenge_rounds.js"],"references":[]},{"id":"chapter-4-5/data.js:d04","mode":"dilemmas","topic":"Ethical dilemmas","prompt":"A client you have supported for several months asks for your home phone number to arrange a social coffee. What is the most professional response?","choices":["Kindly maintain the professional boundary and discuss the request with the supervisor if needed.","Give the number because the client has been pleasant.","Accept and keep the friendship secret from the agency.","Ask the client to pay for the coffee as a thank-you."],"answer":[0],"explain":"A supportive relationship remains professional. The worker should not turn it into a personal social relationship or misuse the position of trust.","source":"Ethics slides, “Code of Ethics”; Chapter 4, “Supporting Mr. Creishilo: Maintaining a Professional Relationship”","originalId":"d04","group":"Chapter 4","bank":"Chapters 4, 5 & 10","sourceFiles":["chapter-4-5/data.js","chapter-4-5/chapter4_focus.js","chapter-4-5/chapter10.js","chapter-4-5/post_ch5_review.js","chapter-4-5/challenge_rounds.js"],"references":[]},{"id":"chapter-4-5/data.js:d05","mode":"dilemmas","topic":"Ethical dilemmas","prompt":"A client declines a planned personal-care task today. The family insists the worker should do it anyway. What is the best next step?","choices":["Respect the client’s refusal, stop, and promptly inform the supervisor.","Proceed because the family has requested it.","Threaten to report the client for refusing.","Ask another worker to complete it without telling the client."],"answer":[0],"explain":"Clients can give or withhold consent and can withdraw consent. Respect the client’s wishes, stop the task, and inform the supervisor rather than allowing family pressure to override the client.","source":"Legislation slides, “Informed Consent”; Chapter 5, “Assault and Battery”","originalId":"d05","group":"Chapter 4","bank":"Chapters 4, 5 & 10","sourceFiles":["chapter-4-5/data.js","chapter-4-5/chapter4_focus.js","chapter-4-5/chapter10.js","chapter-4-5/post_ch5_review.js","chapter-4-5/challenge_rounds.js"],"references":[]},{"id":"chapter-4-5/data.js:d06","mode":"dilemmas","topic":"Ethical dilemmas","prompt":"A client’s son asks you to finish early instead of giving the client the planned bed bath because he is expecting a visitor. What should you do?","choices":["Keep the client’s needs central and contact your supervisor about the request.","Follow the son’s request because he owns the home.","Skip care without informing anyone.","Tell the son he has no right to speak about care."],"answer":[0],"explain":"Beneficence puts the client’s needs first. The textbook example advises focusing on the client’s needs and contacting the supervisor when a family request conflicts with them.","source":"Ethics slides, “Beneficence”; Chapter 4, “Beneficence”","originalId":"d06","group":"Chapter 4","bank":"Chapters 4, 5 & 10","sourceFiles":["chapter-4-5/data.js","chapter-4-5/chapter4_focus.js","chapter-4-5/chapter10.js","chapter-4-5/post_ch5_review.js","chapter-4-5/challenge_rounds.js"],"references":[]},{"id":"chapter-4-5/data.js:r01","mode":"rights","topic":"Client rights & consent","prompt":"A resident can put on his shoes independently, though it takes more time. What should the worker do?","choices":["Allow and encourage him to do as much as he can for himself.","Put the shoes on to keep the schedule moving.","Ask another resident to do it.","Tell him that independence is not part of personal care."],"answer":[0],"explain":"Dignity and independence are closely connected. Encouraging a client to do what they can supports independence and dignity.","source":"Legislation slides, “Dignity and Respect”; Chapter 5, DIPPS and dignity","originalId":"r01","group":"Chapter 5","bank":"Chapters 4, 5 & 10","sourceFiles":["chapter-4-5/data.js","chapter-4-5/chapter4_focus.js","chapter-4-5/chapter10.js","chapter-4-5/post_ch5_review.js","chapter-4-5/challenge_rounds.js"],"references":[]},{"id":"chapter-4-5/data.js:r02","mode":"rights","topic":"Client rights & consent","prompt":"Which option correctly expands DIPPS, a memory aid for dignity-focused care?","choices":["Dignity, Independence, Individualized care, Preferences, Privacy and Safety","Dignity, Information, Protection, Personal choice and Security","Decisions, Independence, Privacy, Professionalism and Support","Dignity, Inclusion, Planning, Prevention and Services"],"answer":[0],"explain":"DIPPS stands for Dignity, Independence, Individualized care, Preferences, Privacy and Safety.","source":"Legislation slides, “Dignity and Respect”; Chapter 5, “The Right to Be Treated With Dignity and Respect”","originalId":"r02","group":"Chapter 5","bank":"Chapters 4, 5 & 10","sourceFiles":["chapter-4-5/data.js","chapter-4-5/chapter4_focus.js","chapter-4-5/chapter10.js","chapter-4-5/post_ch5_review.js","chapter-4-5/challenge_rounds.js"],"references":[]},{"id":"chapter-4-5/data.js:r03","mode":"rights","topic":"Client rights & consent","prompt":"Before a care measure, a client should understand the reason, what will happen, how and who will do it, expected outcomes, risks, alternatives, and likely consequences of refusing. This is the basis of:","choices":["Informed consent","General consent only","A living will","An oath of confidentiality"],"answer":[0],"explain":"Informed consent requires complete, accurate, relevant information so the person understands the proposed action and its implications, including alternatives and consequences of not proceeding.","source":"Legislation slides, “Informed Consent”; Chapter 5, “The Right to Give or Withhold Informed Consent”","originalId":"r03","group":"Chapter 5","bank":"Chapters 4, 5 & 10","sourceFiles":["chapter-4-5/data.js","chapter-4-5/chapter4_focus.js","chapter-4-5/chapter10.js","chapter-4-5/post_ch5_review.js","chapter-4-5/challenge_rounds.js"],"references":[]},{"id":"chapter-4-5/data.js:r04","mode":"rights","topic":"Client rights & consent","prompt":"A client has already signed a consent form but now says “stop” during a procedure. What should the worker do?","choices":["Stop the task and inform the supervisor.","Continue because the signed form cannot be changed.","Ask the family to decide whether to continue.","Finish quickly before the client changes their mind again."],"answer":[0],"explain":"A client may withdraw consent at any time. The worker should respect the client’s wishes, stop the task and inform the supervisor.","source":"Legislation slides, “Battery”; Chapter 5, “Assault and Battery”","originalId":"r04","group":"Chapter 5","bank":"Chapters 4, 5 & 10","sourceFiles":["chapter-4-5/data.js","chapter-4-5/chapter4_focus.js","chapter-4-5/chapter10.js","chapter-4-5/post_ch5_review.js","chapter-4-5/challenge_rounds.js"],"references":[]},{"id":"chapter-4-5/data.js:r05","mode":"rights","topic":"Client rights & consent","prompt":"A client asks whether a surgery is medically necessary and what its risks are. What is the support worker’s role?","choices":["Refer the medical questions to the physician or supervisor; the support worker does not provide medical information.","Explain the risks based on personal experience.","Sign the consent form on the client’s behalf.","Tell the client the family’s preference."],"answer":[0],"explain":"The physician or appropriate health-care provider supplies information about surgery and complex procedures. A support worker is not responsible for providing medical information or obtaining written consent.","source":"Legislation slides, “Decision Maker”; Chapter 5, “The Right to Give or Withhold Informed Consent”","originalId":"r05","group":"Chapter 5","bank":"Chapters 4, 5 & 10","sourceFiles":["chapter-4-5/data.js","chapter-4-5/chapter4_focus.js","chapter-4-5/chapter10.js","chapter-4-5/post_ch5_review.js","chapter-4-5/challenge_rounds.js"],"references":[]},{"id":"chapter-4-5/data.js:r06","mode":"rights","topic":"Client rights & consent","prompt":"A person is unable to understand and provide consent for health care. Who may make decisions on the living person’s behalf?","choices":["An authorized substitute decision maker for health care","The estate trustee, automatically","Any family member who arrives first","The support worker on duty"],"answer":[0],"explain":"A substitute decision maker for health care is authorized to decide for a living person who is unable to do so. The term may be power of attorney for health care or proxy, depending on the province.","source":"Legislation slides, “Advance Directives” and “Decision Maker”; Chapter 5, Key Terms","originalId":"r06","group":"Chapter 5","bank":"Chapters 4, 5 & 10","sourceFiles":["chapter-4-5/data.js","chapter-4-5/chapter4_focus.js","chapter-4-5/chapter10.js","chapter-4-5/post_ch5_review.js","chapter-4-5/challenge_rounds.js"],"references":[]},{"id":"chapter-4-5/data.js:r07","mode":"rights","topic":"Client rights & consent","prompt":"A client calls a document a “living will.” Before relying on that label to determine who may make health-care decisions, what is the safest interpretation?","choices":["Review the document and applicable legal process with the appropriate professional; the label alone does not establish its effect.","Treat the label as proof that the document has no relevance anywhere in Canada.","Treat the label as proof that it appoints the estate executor to make health-care decisions.","Assume the document replaces every current order without further review."],"answer":[0],"explain":"“Living will” is used informally for different advance-planning documents. In BC, advance directives and representation agreements have distinct functions; written wishes can remain relevant even when they are not a valid advance directive. Do not infer legal effect or decision-making authority from the label alone. The original course item’s blanket statement about Canada is not retained.","source":"Legislation slides, “Advance Directives”; Chapter 5, Key Terms and “Advance Directive”","originalId":"r07","group":"Chapter 5","bank":"Chapters 4, 5 & 10","sourceFiles":["chapter-4-5/data.js","chapter-4-5/chapter4_focus.js","chapter-4-5/chapter10.js","chapter-4-5/post_ch5_review.js","chapter-4-5/challenge_rounds.js"],"references":[{"title":"Public Guardian and Trustee of BC · Personal planning tools","href":"https://www.trustee.bc.ca/adults/personal-planning-tools"}]},{"id":"chapter-4-5/data.js:r08","mode":"rights","topic":"Client rights & consent","prompt":"A client dies without leaving a will. Which role is appointed by the provincial courts to administer the estate?","choices":["Administrator","Substitute decision maker for health care","Proxy","Support worker"],"answer":[0],"explain":"An administrator is appointed by the provincial courts to administer an estate when the client dies without a will. An estate trustee/executor is named in a will.","source":"Chapter 5, Key Terms, “administrator” and “estate trustee”","originalId":"r08","group":"Chapter 5","bank":"Chapters 4, 5 & 10","sourceFiles":["chapter-4-5/data.js","chapter-4-5/chapter4_focus.js","chapter-4-5/chapter10.js","chapter-4-5/post_ch5_review.js","chapter-4-5/challenge_rounds.js"],"references":[]},{"id":"chapter-4-5/data.js:r09","mode":"rights","topic":"Client rights & consent","prompt":"A worker assumes a provincial human rights code replaces the Canadian Charter of Rights and Freedoms. Which correction best distinguishes the two?","choices":["The Charter is constitutional; provincial or territorial human rights legislation operates within its own jurisdiction.","The Charter is a facility policy, while a human rights code is constitutional.","A provincial human rights code replaces all constitutional protections in that province.","The Charter and every provincial code are interchangeable names for one statute."],"answer":[0],"explain":"The Charter is part of the Constitution. Human rights statutes are distinct laws with their own jurisdiction and application; do not assume they are interchangeable.","source":"Legislation slides, “Canadian Charter of Rights and Freedoms” and “Basic Rights…”; Chapter 5, “Basic Human Rights in Canada”","originalId":"r09","group":"Chapter 5","bank":"Chapters 4, 5 & 10","sourceFiles":["chapter-4-5/data.js","chapter-4-5/chapter4_focus.js","chapter-4-5/chapter10.js","chapter-4-5/post_ch5_review.js","chapter-4-5/challenge_rounds.js"],"references":[]},{"id":"chapter-4-5/data.js:r10","mode":"rights","topic":"Client rights & consent","prompt":"A client expects a friend to keep a personal conversation private, even though no written law or contract was discussed. This is an example of:","choices":["A moral right based on fairness or ethics","A legal right enforced by a court","An employment standard","A tort"],"answer":[0],"explain":"Moral rights are based on a sense of fairness or ethics. Legal rights are formally recognized in law and enforced by society.","source":"Legislation slides, “Client Rights and Boundaries”; Chapter 5, “Understanding Rights”","originalId":"r10","group":"Chapter 5","bank":"Chapters 4, 5 & 10","sourceFiles":["chapter-4-5/data.js","chapter-4-5/chapter4_focus.js","chapter-4-5/chapter10.js","chapter-4-5/post_ch5_review.js","chapter-4-5/challenge_rounds.js"],"references":[]},{"id":"chapter-4-5/data.js:r11","mode":"rights","topic":"Client rights & consent","prompt":"A learner asks whether every person receiving care in Canada uses one identical, national client Bill of Rights. What is the best answer?","choices":["No. There is no single list for all clients; some provinces and facilities or agencies have bills of rights based on applicable laws.","Yes. One federal Bill of Rights lists every facility rule.","No. Clients have no rights unless a facility writes them down.","Yes. Each employer must use the exact same private policy."],"answer":[0],"explain":"The materials state there is no single list of rights for all Canadians receiving care in facilities or the community. Some provinces and organizations provide bills of rights based on applicable law; workers should know local laws and employer policy.","source":"Legislation slides, “Bill of Rights”; Chapter 5, “Bill of Rights”","originalId":"r11","group":"Chapter 5","bank":"Chapters 4, 5 & 10","sourceFiles":["chapter-4-5/data.js","chapter-4-5/chapter4_focus.js","chapter-4-5/chapter10.js","chapter-4-5/post_ch5_review.js","chapter-4-5/challenge_rounds.js"],"references":[]},{"id":"chapter-4-5/data.js:r12","mode":"rights","topic":"Client rights & consent","prompt":"A provincial Act states general requirements for safe care; detailed rules explain how facilities must meet those requirements. The detailed rules are:","choices":["Regulations","Moral rights","Torts","An advance directive"],"answer":[0],"explain":"An Act is a specific law. Regulations are detailed rules that implement the requirements of a legislative Act.","source":"Legislation slides, “Healthcare Legislation”; Chapter 5, Key Terms","originalId":"r12","group":"Chapter 5","bank":"Chapters 4, 5 & 10","sourceFiles":["chapter-4-5/data.js","chapter-4-5/chapter4_focus.js","chapter-4-5/chapter10.js","chapter-4-5/post_ch5_review.js","chapter-4-5/challenge_rounds.js"],"references":[]},{"id":"chapter-4-5/data.js:t01","mode":"torts","topic":"Legal issues & torts","prompt":"A worker leaves a client’s drainage bag above bladder level, contrary to training, and the client is harmed. Which legal concept best fits?","choices":["Negligence","Assault","Battery","Slander"],"answer":[0],"explain":"Negligence is an unintentional wrong: failing to act carefully or competently and thereby harming a person or property. The chapter gives incorrect drainage-bag positioning as an example.","source":"Legislation slides, “Negligence”; Chapter 5, “Negligence”","originalId":"t01","group":"Chapter 5","bank":"Chapters 4, 5 & 10","sourceFiles":["chapter-4-5/data.js","chapter-4-5/chapter4_focus.js","chapter-4-5/chapter10.js","chapter-4-5/post_ch5_review.js","chapter-4-5/challenge_rounds.js"],"references":[]},{"id":"chapter-4-5/data.js:t02","mode":"torts","topic":"Legal issues & torts","prompt":"A worker threatens to tie down a client who refuses to get into bed. The client fears being harmed. This is:","choices":["Assault","Battery","Negligence","Libel"],"answer":[0],"explain":"Assault is intentionally attempting or threatening to touch someone without consent in a way that causes fear of bodily harm.","source":"Legislation slides, “Assault”; Chapter 5, “Assault and Battery”","originalId":"t02","group":"Chapter 5","bank":"Chapters 4, 5 & 10","sourceFiles":["chapter-4-5/data.js","chapter-4-5/chapter4_focus.js","chapter-4-5/chapter10.js","chapter-4-5/post_ch5_review.js","chapter-4-5/challenge_rounds.js"],"references":[]},{"id":"chapter-4-5/data.js:t03","mode":"torts","topic":"Legal issues & torts","prompt":"A worker force-feeds a client who has refused. No injury occurs. Which concept best describes the unauthorized touching?","choices":["Battery","Assault only","Negligence","False imprisonment"],"answer":[0],"explain":"Battery is actual touching without consent. It does not require an intent to injure; force-feeding is a textbook example.","source":"Legislation slides, “Battery”; Chapter 5, “Assault and Battery”","originalId":"t03","group":"Chapter 5","bank":"Chapters 4, 5 & 10","sourceFiles":["chapter-4-5/data.js","chapter-4-5/chapter4_focus.js","chapter-4-5/chapter10.js","chapter-4-5/post_ch5_review.js","chapter-4-5/challenge_rounds.js"],"references":[]},{"id":"chapter-4-5/data.js:t04","mode":"torts","topic":"Legal issues & torts","prompt":"A worker blocks a client from leaving a facility even though there is no lawful reason to restrict the client’s movement. This may be:","choices":["False imprisonment","Slander","Negligence","Beneficence"],"answer":[0],"explain":"False imprisonment is unlawful restraint or restriction of a person’s freedom of movement. Preventing a client from leaving without lawful reason is an example.","source":"Legislation slides, “False Imprisonment”; Chapter 5, “False Imprisonment”","originalId":"t04","group":"Chapter 5","bank":"Chapters 4, 5 & 10","sourceFiles":["chapter-4-5/data.js","chapter-4-5/chapter4_focus.js","chapter-4-5/chapter10.js","chapter-4-5/post_ch5_review.js","chapter-4-5/challenge_rounds.js"],"references":[]},{"id":"chapter-4-5/data.js:t05","mode":"torts","topic":"Legal issues & torts","prompt":"A worker posts a client’s name and photograph with a comment about the client’s health, without consent. Which tort is most directly implicated?","choices":["Invasion of privacy","Negligence","Assault","False imprisonment"],"answer":[0],"explain":"Publishing a client’s name, photograph, health information or private affairs without consent violates privacy and may be an invasion of privacy.","source":"Legislation slides, “Electronic Privacy” and “Invasion of Privacy”; Chapter 5, “Electronic Privacy”","originalId":"t05","group":"Chapter 5","bank":"Chapters 4, 5 & 10","sourceFiles":["chapter-4-5/data.js","chapter-4-5/chapter4_focus.js","chapter-4-5/chapter10.js","chapter-4-5/post_ch5_review.js","chapter-4-5/challenge_rounds.js"],"references":[]},{"id":"chapter-4-5/data.js:t06","mode":"torts","topic":"Legal issues & torts","prompt":"A worker knowingly tells another person a false, harmful story about a client’s reputation. What is the general term?","choices":["Defamation","Battery","False imprisonment","Beneficence"],"answer":[0],"explain":"Defamation injures someone’s name and reputation through false statements to a third person. Written false statements are libel; harmful false statements spoken orally are slander.","source":"Legislation slides, “Defamation of Character”; Chapter 5, “Defamation of Character”","originalId":"t06","group":"Chapter 5","bank":"Chapters 4, 5 & 10","sourceFiles":["chapter-4-5/data.js","chapter-4-5/chapter4_focus.js","chapter-4-5/chapter10.js","chapter-4-5/post_ch5_review.js","chapter-4-5/challenge_rounds.js"],"references":[]},{"id":"chapter-4-5/data.js:t07","mode":"torts","topic":"Legal issues & torts","prompt":"Which comparison of criminal and civil law is accurate?","choices":["Criminal laws address offences against the public and society; civil laws deal with relationships between people.","Criminal laws cover only workplace disputes; civil laws cover only abuse.","Civil laws are rules set by a facility; criminal laws are professional values.","The terms describe the same legal process."],"answer":[0],"explain":"Criminal laws concern offences against the public and society. Civil laws deal with relationships between people; torts are wrongful acts against a person or property.","source":"Legislation slides, “Legal Issues”; Chapter 5, “Understanding Legal Issues”","originalId":"t07","group":"Chapter 5","bank":"Chapters 4, 5 & 10","sourceFiles":["chapter-4-5/data.js","chapter-4-5/chapter4_focus.js","chapter-4-5/chapter10.js","chapter-4-5/post_ch5_review.js","chapter-4-5/challenge_rounds.js"],"references":[]},{"id":"chapter-4-5/data.js:t08","mode":"torts","topic":"Legal issues & torts","prompt":"A worker is asked to perform a task that was never delegated or taught, and it is outside the worker’s competencies. What is the safest response?","choices":["Do not perform it; explain the limit and seek direction from the supervisor or regulated health-care professional.","Try it carefully because the family requested it.","Ask the client to show how it is done.","Proceed once, then document it afterward."],"answer":[0],"explain":"Stay within the role, training, employer policy and delegated responsibilities. Taking on an untrained task can harm the client and create legal and ethical risk.","source":"Ethics slides, “Nonmaleficence”; Legislation slides, “Awareness of Your Role”; Chapters 4–5","originalId":"t08","group":"Chapter 5","bank":"Chapters 4, 5 & 10","sourceFiles":["chapter-4-5/data.js","chapter-4-5/chapter4_focus.js","chapter-4-5/chapter10.js","chapter-4-5/post_ch5_review.js","chapter-4-5/challenge_rounds.js"],"references":[]},{"id":"chapter-4-5/data.js:v01","mode":"privacy","topic":"Privacy & confidentiality","prompt":"A client receives personal care in a shared room. Which action best respects the client’s privacy?","choices":["Close curtains or doors and expose only what is necessary; limit viewing to staff involved in care.","Leave the door open so coworkers can check in.","Ask visitors to help because they are already in the room.","Discuss the care task with other residents."],"answer":[0],"explain":"Clients have the right to care in private without unnecessary exposure. Only those involved in the person’s care should see or handle the client’s body.","source":"Legislation slides, “Privacy and Confidentiality”; Chapter 5, “The Right to Privacy and Confidentiality”","originalId":"v01","group":"Chapter 5","bank":"Chapters 4, 5 & 10","sourceFiles":["chapter-4-5/data.js","chapter-4-5/chapter4_focus.js","chapter-4-5/chapter10.js","chapter-4-5/post_ch5_review.js","chapter-4-5/challenge_rounds.js"],"references":[]},{"id":"chapter-4-5/data.js:v02","mode":"privacy","topic":"Privacy & confidentiality","prompt":"A coworker asks about a client’s condition while you are in a public elevator. What should you do?","choices":["Wait to discuss any necessary information privately and only with team members who need it for care.","Share a short summary because the coworker is on staff.","Use the client’s initials so nearby people will not know.","Discuss it quietly with the coworker in the elevator."],"answer":[0],"explain":"Confidential information should be shared only as needed with the health-care team, in a private setting. Public spaces can allow others to overhear.","source":"Ethics slides, “Code of Ethics”; Chapter 4, “Justice”; Chapter 5, “The Right to Privacy and Confidentiality”","originalId":"v02","group":"Chapter 5","bank":"Chapters 4, 5 & 10","sourceFiles":["chapter-4-5/data.js","chapter-4-5/chapter4_focus.js","chapter-4-5/chapter10.js","chapter-4-5/post_ch5_review.js","chapter-4-5/challenge_rounds.js"],"references":[]},{"id":"chapter-4-5/data.js:v03","mode":"privacy","topic":"Privacy & confidentiality","prompt":"A worker sees a client’s fall during a home-care visit and wonders whether to post a vague story online without naming the client. What is the safest choice?","choices":["Do not post about the client or care event; report and document it through approved workplace channels.","Post it if the client’s name is omitted.","Post it to a private account visible only to friends.","Share a photo after covering the client’s face."],"answer":[0],"explain":"Electronic privacy covers images, words and descriptions made public through electronic means. Removing a name or hiding a face does not make posting a client’s care information appropriate.","source":"Legislation slides, “Electronic Privacy”; Chapter 5, “Electronic Privacy”","originalId":"v03","group":"Chapter 5","bank":"Chapters 4, 5 & 10","sourceFiles":["chapter-4-5/data.js","chapter-4-5/chapter4_focus.js","chapter-4-5/chapter10.js","chapter-4-5/post_ch5_review.js","chapter-4-5/challenge_rounds.js"],"references":[]},{"id":"chapter-4-5/data.js:v04","mode":"privacy","topic":"Privacy & confidentiality","prompt":"A client’s family asks whether the client has been diagnosed with a particular illness. What is the worker’s best response?","choices":["Do not confirm or explain the diagnosis; refer the question to the supervisor or appropriate clinician.","Answer if the family says they already know.","Share only what the worker heard from another staff member.","Give an opinion but label it as uncertain."],"answer":[0],"explain":"Diagnosis and treatment information is confidential and outside a support worker’s role to explain. Refer questions to the supervisor or appropriate clinician.","source":"Ethics slides, “Nonmaleficence”; Chapter 4, “Nonmaleficence”; Chapter 5, privacy rights","originalId":"v04","group":"Chapter 5","bank":"Chapters 4, 5 & 10","sourceFiles":["chapter-4-5/data.js","chapter-4-5/chapter4_focus.js","chapter-4-5/chapter10.js","chapter-4-5/post_ch5_review.js","chapter-4-5/challenge_rounds.js"],"references":[]},{"id":"chapter-4-5/data.js:v05","mode":"privacy","topic":"Privacy & confidentiality","prompt":"A client’s care is documented on an agency tablet. Which practice best protects electronic privacy?","choices":["Use the device and records only as authorized by agency policy; keep the information private and secure.","Take a screenshot to finish the note at home.","Send the details through a personal messaging account.","Leave the record open so the next person can find it."],"answer":[0],"explain":"Agencies may use electronic devices for care records, but privacy rules and employer procedures still apply. Follow approved handling, access and communication practices.","source":"Legislation slides, “Electronic Privacy”; Chapter 5, “The Right to Privacy and Confidentiality”","originalId":"v05","group":"Chapter 5","bank":"Chapters 4, 5 & 10","sourceFiles":["chapter-4-5/data.js","chapter-4-5/chapter4_focus.js","chapter-4-5/chapter10.js","chapter-4-5/post_ch5_review.js","chapter-4-5/challenge_rounds.js"],"references":[]},{"id":"chapter-4-5/data.js:v06","mode":"privacy","topic":"Privacy & confidentiality","prompt":"A client has asked you not to tell anyone that they fell, but they now report pain and difficulty standing. What is the best response?","choices":["Explain that you must report the change to the supervisor for the client’s safety, then share only through the proper care channel.","Promise secrecy and leave the client resting.","Tell the client’s neighbours so they can monitor the situation.","Wait until the next scheduled visit."],"answer":[0],"explain":"Confidentiality does not mean withholding important safety information from the care team. Report relevant observations to the supervisor and keep the information within appropriate channels.","source":"Ethics slides, “Code of Ethics” and “Ethical Dilemmas”; Chapter 4, sample code; Chapter 5, confidentiality","originalId":"v06","group":"Chapter 5","bank":"Chapters 4, 5 & 10","sourceFiles":["chapter-4-5/data.js","chapter-4-5/chapter4_focus.js","chapter-4-5/chapter10.js","chapter-4-5/post_ch5_review.js","chapter-4-5/challenge_rounds.js"],"references":[]},{"id":"chapter-4-5/data.js:w01","mode":"workers","topic":"Worker rights & safe practice","prompt":"A client requests that the agency send only workers of a particular race. What is the appropriate principle for the employer?","choices":["The employer must not discriminate against workers at a client’s request.","The employer must grant the request because clients control staffing.","The employer should ask workers to exchange shifts informally.","The employer may ignore human-rights protections in home care."],"answer":[0],"explain":"Human rights legislation requires equal treatment and prohibits discrimination on protected grounds. The chapter states that employers and employment agencies cannot discriminate at a client’s request.","source":"Legislation slides, “Human Rights Legislation”; Chapter 5, “Human Rights Legislation”","originalId":"w01","group":"Chapter 5","bank":"Chapters 4, 5 & 10","sourceFiles":["chapter-4-5/data.js","chapter-4-5/chapter4_focus.js","chapter-4-5/chapter10.js","chapter-4-5/post_ch5_review.js","chapter-4-5/challenge_rounds.js"],"references":[]},{"id":"chapter-4-5/data.js:w02","mode":"workers","topic":"Worker rights & safe practice","prompt":"A supervisor has not provided training for a hazardous task. Which worker protection is most relevant?","choices":["The right to proper education, instruction and supervision to help ensure safety.","A guaranteed right to perform any task once assigned.","A right to skip all documentation.","A right to decide the client’s care plan."],"answer":[0],"explain":"Occupational health and safety legislation sets out responsibilities for a safe workplace. Workers have a right to proper education, instruction and supervision.","source":"Legislation slides, “Occupational Health and Safety Legislation”; Chapter 5, same section","originalId":"w02","group":"Chapter 5","bank":"Chapters 4, 5 & 10","sourceFiles":["chapter-4-5/data.js","chapter-4-5/chapter4_focus.js","chapter-4-5/chapter10.js","chapter-4-5/post_ch5_review.js","chapter-4-5/challenge_rounds.js"],"references":[]},{"id":"chapter-4-5/data.js:w03","mode":"workers","topic":"Worker rights & safe practice","prompt":"A worker believes an assigned duty could endanger the worker or another person. Which workplace right is most relevant?","choices":["The right to refuse work that poses a danger, while following applicable procedures and considering any health-care exceptions.","The right to leave without notifying anyone.","The right to delegate the work to a client.","The right to continue because a supervisor assigned it."],"answer":[0],"explain":"Workers generally have the right to refuse work that poses a danger to themselves or others. The textbook notes some provincial or territorial exceptions for health-care workers when refusal would endanger a client; follow local law and workplace procedures.","source":"Legislation slides, “Occupational Health and Safety Legislation”; Chapter 5, same section","originalId":"w03","group":"Chapter 5","bank":"Chapters 4, 5 & 10","sourceFiles":["chapter-4-5/data.js","chapter-4-5/chapter4_focus.js","chapter-4-5/chapter10.js","chapter-4-5/post_ch5_review.js","chapter-4-5/challenge_rounds.js"],"references":[]},{"id":"chapter-4-5/data.js:w04","mode":"workers","topic":"Worker rights & safe practice","prompt":"A worker needs to identify safe handling information for a hazardous product used at work. Which system provides it?","choices":["WHMIS — Workplace Hazardous Materials Information System","DIPPS — Dignity, Independence, Individualized care, Preferences, Privacy and Safety","Collective bargaining","Workers’ compensation"],"answer":[0],"explain":"WHMIS provides information on safe use and potential health risks of hazardous materials.","source":"Legislation slides, “Occupational Health and Safety Legislation”; Chapter 5, same section","originalId":"w04","group":"Chapter 5","bank":"Chapters 4, 5 & 10","sourceFiles":["chapter-4-5/data.js","chapter-4-5/chapter4_focus.js","chapter-4-5/chapter10.js","chapter-4-5/post_ch5_review.js","chapter-4-5/challenge_rounds.js"],"references":[]},{"id":"chapter-4-5/data.js:w05","mode":"workers","topic":"Worker rights & safe practice","prompt":"A worker wants to understand minimum wage, overtime pay, vacation days and leave entitlements. Which legislation addresses these minimum standards?","choices":["Employment standards legislation","Labour relations legislation","Workers’ compensation legislation","Privacy legislation"],"answer":[0],"explain":"Employment standards legislation covers minimum wage, payment of wages, work hours, overtime, holidays, vacation and qualifying leaves.","source":"Legislation slides, “Employment Standards Legislation”; Chapter 5, same section","originalId":"w05","group":"Chapter 5","bank":"Chapters 4, 5 & 10","sourceFiles":["chapter-4-5/data.js","chapter-4-5/chapter4_focus.js","chapter-4-5/chapter10.js","chapter-4-5/post_ch5_review.js","chapter-4-5/challenge_rounds.js"],"references":[]},{"id":"chapter-4-5/data.js:w06","mode":"workers","topic":"Worker rights & safe practice","prompt":"Employees join together to negotiate wages and other workplace issues with an employer. Which concept is most directly involved?","choices":["Labour relations legislation and collective bargaining","Workers’ compensation","Informed consent","Estate administration"],"answer":[0],"explain":"Labour relations legislation addresses workplace issues, union membership and negotiation rules. Negotiation by a union on behalf of its members is collective bargaining.","source":"Legislation slides, “Labour Relations Legislation”; Chapter 5, same section","originalId":"w06","group":"Chapter 5","bank":"Chapters 4, 5 & 10","sourceFiles":["chapter-4-5/data.js","chapter-4-5/chapter4_focus.js","chapter-4-5/chapter10.js","chapter-4-5/post_ch5_review.js","chapter-4-5/challenge_rounds.js"],"references":[]},{"id":"chapter-4-5/data.js:w07","mode":"workers","topic":"Worker rights & safe practice","prompt":"A worker is accidentally injured while doing a job-related task. Which legislation addresses financial compensation for accidental injuries on the job?","choices":["Workers’ compensation legislation","Employment standards legislation","The Canadian Charter of Rights and Freedoms","An advance directive"],"answer":[0],"explain":"Workers’ compensation legislation addresses financial compensation and rights and responsibilities when a work-related injury occurs.","source":"Legislation slides, “Workers’ Compensation Legislation”; Chapter 5, same section","originalId":"w07","group":"Chapter 5","bank":"Chapters 4, 5 & 10","sourceFiles":["chapter-4-5/data.js","chapter-4-5/chapter4_focus.js","chapter-4-5/chapter10.js","chapter-4-5/post_ch5_review.js","chapter-4-5/challenge_rounds.js"],"references":[]},{"id":"chapter-4-5/data.js:w08","mode":"workers","topic":"Worker rights & safe practice","prompt":"A procedure was allowed at one agency, but you are unsure whether it is allowed at your new placement. What is the safest next step?","choices":["Check the current employer policy and ask the supervisor or regulated health-care professional before proceeding.","Assume the previous agency’s permission applies everywhere.","Ask the client to authorize the task.","Proceed if you remember seeing it done before."],"answer":[0],"explain":"Policies and permitted skills can differ between agencies. Do not assume duties transfer automatically; ask for direction when unsure and stay within training and role boundaries.","source":"Ethics slides, “Code of Ethics”; Chapter 4, Box 4.1, sample code","originalId":"w08","group":"Chapter 5","bank":"Chapters 4, 5 & 10","sourceFiles":["chapter-4-5/data.js","chapter-4-5/chapter4_focus.js","chapter-4-5/chapter10.js","chapter-4-5/post_ch5_review.js","chapter-4-5/challenge_rounds.js"],"references":[]},{"id":"chapter-4-5/data.js:e07","mode":"terms","topic":"Ethics & terminology","prompt":"A support worker is not part of a regulated profession with a regulator-issued code of ethics. Which statement best describes the worker’s responsibilities?","choices":["The worker remains accountable to laws, employer policies, job description, care plan and professional boundaries.","The worker is not accountable for workplace conduct.","Only a personal moral code applies to support work.","The client’s family may replace all employer policies."],"answer":[0],"explain":"The Ethics slides distinguish regulator-issued codes for regulated professions from employer codes of conduct that may guide support workers. Being unregulated does not remove accountability to laws, policies, the job description, care plans and professional boundaries.","source":"Ethics PowerPoint, “Code of Ethics”; Therese’s Chapter 4 Ethics Consolidated Arcade Notes","originalId":"e07","group":"Chapter 4","bank":"Chapters 4, 5 & 10","sourceFiles":["chapter-4-5/data.js","chapter-4-5/chapter4_focus.js","chapter-4-5/chapter10.js","chapter-4-5/post_ch5_review.js","chapter-4-5/challenge_rounds.js"],"references":[]},{"id":"chapter-4-5/data.js:e08","mode":"terms","topic":"Ethics & terminology","prompt":"A client you know well asks you to do a personal favour that is outside your assigned role. What is the most professional response?","choices":["Politely explain that you cannot do an unauthorized favour and refer the request to your supervisor.","Agree because you have developed a close relationship.","Keep it secret so the agency does not misunderstand.","Ask the client’s family to pay you directly."],"answer":[0],"explain":"Compassion does not make a support worker the client’s friend or family member. Maintain professional boundaries, politely decline unauthorized personal favours and seek supervisory guidance.","source":"Ethics PowerPoint, “Code of Ethics”; Therese’s Chapter 4 Ethics Consolidated Arcade Notes","originalId":"e08","group":"Chapter 4","bank":"Chapters 4, 5 & 10","sourceFiles":["chapter-4-5/data.js","chapter-4-5/chapter4_focus.js","chapter-4-5/chapter10.js","chapter-4-5/post_ch5_review.js","chapter-4-5/challenge_rounds.js"],"references":[]},{"id":"chapter-4-5/data.js:p09","mode":"principles","topic":"Four principles","prompt":"A capable client refuses a bath. What response best respects autonomy while keeping the care team informed?","choices":["Ask respectfully why, offer reasonable alternatives, do not force the client, and report the refusal according to policy.","Proceed because bathing is part of the care plan.","Tell the client they are being unreasonable and leave.","Ask the family to overrule the client."],"answer":[0],"explain":"Autonomy is self-determination and includes the right to refuse. Explore the reason and alternatives respectfully, do not force a capable client, and follow workplace policy for reporting and objective documentation.","source":"Ethics PowerPoint, “Autonomy”; Therese’s Chapter 4 Ethics Consolidated Arcade Notes","originalId":"p09","group":"Chapter 4","bank":"Chapters 4, 5 & 10","sourceFiles":["chapter-4-5/data.js","chapter-4-5/chapter4_focus.js","chapter-4-5/chapter10.js","chapter-4-5/post_ch5_review.js","chapter-4-5/challenge_rounds.js"],"references":[]},{"id":"chapter-4-5/data.js:p10","mode":"principles","topic":"Four principles","prompt":"A client expresses frustration and makes repeated requests. The worker is tempted to shorten the visit despite unchanged care needs. Which action best demonstrates justice?","choices":["Provide fair, attentive care based on the client’s needs, without reducing respect because of temperament.","Spend less time with the client because others are easier to help.","Offer better care only if the client becomes pleasant.","Ask a coworker to take over every visit."],"answer":[0],"explain":"Justice means treating clients fairly and equally. Individual needs may differ, but a client’s temperament should not lead to less appropriate attention or respect.","source":"Ethics PowerPoint, “Justice”; Therese’s Chapter 4 Ethics Consolidated Arcade Notes","originalId":"p10","group":"Chapter 4","bank":"Chapters 4, 5 & 10","sourceFiles":["chapter-4-5/data.js","chapter-4-5/chapter4_focus.js","chapter-4-5/chapter10.js","chapter-4-5/post_ch5_review.js","chapter-4-5/challenge_rounds.js"],"references":[]},{"id":"chapter-4-5/data.js:p11","mode":"principles","topic":"Four principles","prompt":"A family member asks you to skip a planned care activity for convenience, but it conflicts with the client’s stated needs and care plan. Which principle most directly emphasizes doing what benefits the client?","choices":["Beneficence","Autonomy","Justice","Nonmaleficence"],"answer":[0],"explain":"Beneficence means doing or promoting good. The client’s needs come before conflicting family preferences; check the care plan and contact the supervisor rather than acting on an unauthorized request.","source":"Ethics PowerPoint, “Beneficence”; Therese’s Chapter 4 Ethics Consolidated Arcade Notes","originalId":"p11","group":"Chapter 4","bank":"Chapters 4, 5 & 10","sourceFiles":["chapter-4-5/data.js","chapter-4-5/chapter4_focus.js","chapter-4-5/chapter10.js","chapter-4-5/post_ch5_review.js","chapter-4-5/challenge_rounds.js"],"references":[]},{"id":"chapter-4-5/data.js:p12","mode":"principles","topic":"Four principles","prompt":"A client’s family asks you to explain what a diagnosis means and what treatment the doctor plans. What response best reflects nonmaleficence?","choices":["Do not interpret the diagnosis or treatment plan; refer their question to the nurse or supervisor.","Guess based on the client’s symptoms to reassure the family.","Read the medical report aloud but say you are not a nurse.","Ask another support worker what the diagnosis means."],"answer":[0],"explain":"Nonmaleficence means seeking to do no harm. Interpreting a diagnosis or medical plan is outside the support worker’s role and risks giving inaccurate information; refer the question and report relevant concerns through authorized channels.","source":"Ethics PowerPoint, “Nonmaleficence”; Therese’s Chapter 4 Ethics Consolidated Arcade Notes","originalId":"p12","group":"Chapter 4","bank":"Chapters 4, 5 & 10","sourceFiles":["chapter-4-5/data.js","chapter-4-5/chapter4_focus.js","chapter-4-5/chapter10.js","chapter-4-5/post_ch5_review.js","chapter-4-5/challenge_rounds.js"],"references":[]},{"id":"chapter-4-5/data.js:d14","mode":"dilemmas","topic":"Ethical dilemmas","prompt":"Two opposing moral choices each appear to have a reason in their favour, and choosing one means going against the other. What is this situation?","choices":["An ethical dilemma","A professional boundary","A code of conduct","A routine assignment"],"answer":[0],"explain":"An ethical dilemma is a situation involving an apparent conflict between opposing moral choices. A code of ethics guides conduct but cannot provide an answer for every situation.","source":"Ethics PowerPoint, “Ethical Dilemmas”; Chapter 4 Key Terms; Therese’s notes","originalId":"d14","group":"Chapter 4","bank":"Chapters 4, 5 & 10","sourceFiles":["chapter-4-5/data.js","chapter-4-5/chapter4_focus.js","chapter-4-5/chapter10.js","chapter-4-5/post_ch5_review.js","chapter-4-5/challenge_rounds.js"],"references":[]},{"id":"chapter-4-5/data.js:d07","mode":"dilemmas","topic":"Ethical dilemmas","prompt":"You are unsure how to respond to a family request that conflicts with a client’s preferences. What is the sound sequence for working through this dilemma?","choices":["Consider the four principles, collect relevant information and compare possible options.","Apply the client’s preference immediately, then collect information about consequences.","Collect the family’s account, choose a familiar response and check the client’s view afterward.","Choose the option with the least short-term risk, then consider the other principles if it fails."],"answer":[0],"explain":"The Ethics PowerPoint gives three steps: carefully consider the four ethical principles, collect as much information as possible, and consider all possible options. It does not name a longer step-by-step algorithm.","source":"Ethics PowerPoint, “Dealing with Ethical Dilemmas”; Therese’s Chapter 4 Ethics Consolidated Arcade Notes","originalId":"d07","group":"Chapter 4","bank":"Chapters 4, 5 & 10","sourceFiles":["chapter-4-5/data.js","chapter-4-5/chapter4_focus.js","chapter-4-5/chapter10.js","chapter-4-5/post_ch5_review.js","chapter-4-5/challenge_rounds.js"],"references":[]},{"id":"chapter-4-5/data.js:d08","mode":"dilemmas","topic":"Ethical dilemmas","prompt":"When evaluating a possible response to an ethical dilemma, which set of checks is most complete?","choices":["Does it respect the client’s wishes; treat them fairly; provide short- or long-term benefit; risk harm; and what consequences could it have for the client, family or others?","Is it fastest; does the family agree; is it familiar; can it be kept private; does it avoid paperwork?","Does it follow the worker’s personal values; make the client comply; satisfy the family; save time; avoid discussion?","Is it legal; requested by a coworker; easy to document; common at work; likely to avoid complaints?"],"answer":[0],"explain":"Evaluate options by asking whether they respect wishes and preferences (autonomy), treat the client justly (justice), provide short- or long-term benefit (beneficence), risk harm (nonmaleficence), and what consequences may follow for the client, family or others.","source":"Ethics PowerPoint, “Questions to Ask Yourself…”; Therese’s Chapter 4 Ethics Consolidated Arcade Notes","originalId":"d08","group":"Chapter 4","bank":"Chapters 4, 5 & 10","sourceFiles":["chapter-4-5/data.js","chapter-4-5/chapter4_focus.js","chapter-4-5/chapter10.js","chapter-4-5/post_ch5_review.js","chapter-4-5/challenge_rounds.js"],"references":[]},{"id":"chapter-4-5/data.js:d09","mode":"dilemmas","topic":"Ethical dilemmas","prompt":"A client refuses a bath, while a family member insists you proceed. Which response best balances the principles and professional responsibilities?","choices":["Respect the client’s refusal, ask about the reason and alternatives, then report and document objectively under workplace policy.","Follow the family’s request because they know the client best.","Force the bath because it is listed in the care plan.","Ignore the refusal and do not mention it to anyone."],"answer":[0],"explain":"Autonomy supports the capable client’s right to refuse. Beneficence and nonmaleficence call for considering the client’s needs and possible risks. Explore alternatives respectfully and report the facts according to policy.","source":"Ethics PowerPoint, “Autonomy” and “Questions to Ask Yourself…”; Therese’s Chapter 4 Ethics Consolidated Arcade Notes","originalId":"d09","group":"Chapter 4","bank":"Chapters 4, 5 & 10","sourceFiles":["chapter-4-5/data.js","chapter-4-5/chapter4_focus.js","chapter-4-5/chapter10.js","chapter-4-5/post_ch5_review.js","chapter-4-5/challenge_rounds.js"],"references":[]},{"id":"chapter-4-5/data.js:d10","mode":"dilemmas","topic":"Ethical dilemmas","prompt":"A family asks whether the client ate breakfast because they are concerned about recent weight loss. What is an appropriate response within your role?","choices":["Share authorized factual observations through approved private channels, avoid guessing at medical meaning, and report the concern to the nurse.","Explain that reduced appetite means the client’s medication is wrong.","Tell the family the diagnosis you suspect.","Refuse to share any observation even with the care team."],"answer":[0],"explain":"Support workers may report firsthand daily-care observations to authorized recipients according to privacy and employer policy. Do not diagnose or speculate about causes; report the family’s concern to the nurse.","source":"Ethics PowerPoint, “Nonmaleficence”; Therese’s Chapter 4 Ethics Consolidated Arcade Notes","originalId":"d10","group":"Chapter 4","bank":"Chapters 4, 5 & 10","sourceFiles":["chapter-4-5/data.js","chapter-4-5/chapter4_focus.js","chapter-4-5/chapter10.js","chapter-4-5/post_ch5_review.js","chapter-4-5/challenge_rounds.js"],"references":[]},{"id":"chapter-4-5/data.js:d11","mode":"dilemmas","topic":"Ethical dilemmas","prompt":"You complete an optional course on a clinical skill. A client then asks you to perform that skill, but your job description and authorization do not include it. What should you do?","choices":["Do not perform it based on the course alone; clarify with the supervisor and follow policy and authorization limits.","Perform it because additional training automatically expands your role.","Ask the client to accept responsibility if anything goes wrong.","Teach the skill to a coworker and let them decide."],"answer":[0],"explain":"Ongoing education helps maintain and develop knowledge, but training by itself does not expand a worker’s authorization. Follow the job description, employer policy, care plan and supervisor direction.","source":"Ethics PowerPoint, “Continuing Education”; Therese’s Chapter 4 Ethics Consolidated Arcade Notes","originalId":"d11","group":"Chapter 4","bank":"Chapters 4, 5 & 10","sourceFiles":["chapter-4-5/data.js","chapter-4-5/chapter4_focus.js","chapter-4-5/chapter10.js","chapter-4-5/post_ch5_review.js","chapter-4-5/challenge_rounds.js"],"references":[]},{"id":"chapter-4-5/data.js:t10-01","chapter":10,"mode":"teamwork","topic":"Teamwork & collaboration","prompt":"At a team meeting, a support worker who sees a client daily reports that the client has stopped reading, seems less outgoing and says exercises cause sharp pain. Why is this input valuable?","choices":["It adds day-to-day observations that help the team build a fuller picture and decide what follow-up is needed.","It lets the support worker diagnose depression and change the exercise plan.","It replaces the need for the client’s own views.","It gives the support worker authority to direct the physiotherapist."],"answer":[0],"explain":"Support workers often have frequent contact and can contribute observations that other team members may not see. The team can use that information to decide what assessment or follow-up is appropriate.","source":"Teamwork slides, “Interprofessional Collaborative Practice”; Chapter 10, Box 10.1","originalId":"t10-01","group":"Chapter 10","bank":"Chapters 4, 5 & 10","sourceFiles":["chapter-4-5/data.js","chapter-4-5/chapter4_focus.js","chapter-4-5/chapter10.js","chapter-4-5/post_ch5_review.js","chapter-4-5/challenge_rounds.js"],"references":[]},{"id":"chapter-4-5/data.js:t10-02","chapter":10,"mode":"teamwork","topic":"Teamwork & collaboration","prompt":"A client cannot afford the taxi fare to attend physiotherapy and tells you they have missed several visits. What is the best team response?","choices":["Acknowledge the concern, report it through the care team, and explore support options with the client’s permission.","Arrange a ride with a volunteer and share the client’s details without asking.","Tell the client that transportation is outside everyone’s role.","Advise the client to stop physiotherapy until finances improve."],"answer":[0],"explain":"The support worker can report the barrier and contribute to collaborative problem-solving. In the chapter example, the client’s permission was obtained before a volunteer group arranged transportation.","source":"Chapter 10, “Supporting Mr. Rodriguez: How Team Input Can Make a Difference”; teamwork slides","originalId":"t10-02","group":"Chapter 10","bank":"Chapters 4, 5 & 10","sourceFiles":["chapter-4-5/data.js","chapter-4-5/chapter4_focus.js","chapter-4-5/chapter10.js","chapter-4-5/post_ch5_review.js","chapter-4-5/challenge_rounds.js"],"references":[]},{"id":"chapter-4-5/data.js:t10-03","chapter":10,"mode":"teamwork","topic":"Teamwork & collaboration","prompt":"During a care conference, the client and family are invited to share concerns and participate in decisions. Which teamwork approach does this reflect?","choices":["Interprofessional collaborative practice with the client and family included in the process.","A team structure where only regulated professionals make decisions.","Delegation of decision-making to the support worker.","A private contract between the client and each team member."],"answer":[0],"explain":"The slides describe shared decision-making and leadership, clear understanding of each provider’s role, and client and family participation as features of interprofessional collaboration.","source":"Teamwork slides, “Interprofessional Collaborative Practice”; Chapter 10, “Teamwork in Facilities”","originalId":"t10-03","group":"Chapter 10","bank":"Chapters 4, 5 & 10","sourceFiles":["chapter-4-5/data.js","chapter-4-5/chapter4_focus.js","chapter-4-5/chapter10.js","chapter-4-5/post_ch5_review.js","chapter-4-5/challenge_rounds.js"],"references":[]},{"id":"chapter-4-5/data.js:t10-04","chapter":10,"mode":"teamwork","topic":"Teamwork & collaboration","prompt":"A community client’s care requires coordination among several providers. Who usually assesses, monitors and evaluates the client’s needs and coordinates community services?","choices":["The case manager or team leader.","The support worker with the most visits.","The client’s family member who attends meetings.","The employer’s payroll administrator."],"answer":[0],"explain":"In community care, the case manager or team leader coordinates services and assesses, monitors and evaluates needs. This person may be a nurse, social worker or another regulated health-care provider.","source":"Chapter 10, “Teamwork in Community Settings”; teamwork slides","originalId":"t10-04","group":"Chapter 10","bank":"Chapters 4, 5 & 10","sourceFiles":["chapter-4-5/data.js","chapter-4-5/chapter4_focus.js","chapter-4-5/chapter10.js","chapter-4-5/post_ch5_review.js","chapter-4-5/challenge_rounds.js"],"references":[]},{"id":"chapter-4-5/data.js:t10-05","chapter":10,"mode":"teamwork","topic":"Teamwork & collaboration","prompt":"A new support worker is learning a facility’s routines. An experienced colleague shares knowledge, answers questions and creates a safe learning environment. What role is the colleague providing?","choices":["Mentorship.","Delegation.","Case management.","Family conferencing."],"answer":[0],"explain":"A mentor shares expertise and knowledge to create a safe, encouraging learning environment for a learner.","source":"Chapter 10, Key Terms; teamwork slides, “Benefits of Working on a Team”","originalId":"t10-05","group":"Chapter 10","bank":"Chapters 4, 5 & 10","sourceFiles":["chapter-4-5/data.js","chapter-4-5/chapter4_focus.js","chapter-4-5/chapter10.js","chapter-4-5/post_ch5_review.js","chapter-4-5/challenge_rounds.js"],"references":[]},{"id":"chapter-4-5/data.js:t10-06","chapter":10,"mode":"teamwork","topic":"Teamwork & collaboration","prompt":"A client declines to attend a scheduled care conference. What is the best understanding of the meeting?","choices":["It is a meeting for the team and family to discuss care; the client may participate if they choose and are able.","It cannot proceed unless the client attends.","It is only for the family to receive confidential details from the support worker.","It gives the family authority to assign tasks to staff."],"answer":[0],"explain":"A family conference (also called a care conference) brings the health-care team and family together to discuss care. The chapter describes client attendance when possible; a client may choose not to attend.","source":"Chapter 10, “Teamwork in Facilities”; teamwork slides, “Family conference (care conference)”","originalId":"t10-06","group":"Chapter 10","bank":"Chapters 4, 5 & 10","sourceFiles":["chapter-4-5/data.js","chapter-4-5/chapter4_focus.js","chapter-4-5/chapter10.js","chapter-4-5/post_ch5_review.js","chapter-4-5/challenge_rounds.js"],"references":[]},{"id":"chapter-4-5/data.js:t10-07","chapter":10,"mode":"teamwork","topic":"Teamwork & collaboration","prompt":"A nurse and support worker disagree about how to adapt a client’s routine. What team practice is most likely to help reach a sound decision?","choices":["Discuss the issue respectfully, consider the client’s needs and each person’s role, and share relevant observations.","Have the support worker make the final decision because they see the client most often.","Avoid raising the concern so the disagreement goes away.","Ask uninvolved coworkers to take sides."],"answer":[0],"explain":"Communication and collaboration bring different perspectives together. Team members should respect scope and discuss concerns rather than letting conflict go unresolved.","source":"Chapter 10, “Benefits of Working on a Team” and “Conflict in the Workplace”; teamwork slides","originalId":"t10-07","group":"Chapter 10","bank":"Chapters 4, 5 & 10","sourceFiles":["chapter-4-5/data.js","chapter-4-5/chapter4_focus.js","chapter-4-5/chapter10.js","chapter-4-5/post_ch5_review.js","chapter-4-5/challenge_rounds.js"],"references":[]},{"id":"chapter-4-5/data.js:t10-08","chapter":10,"mode":"teamwork","topic":"Teamwork & collaboration","prompt":"A team meeting compares an ongoing-care residence with a hospice service. Which distinction is most accurate?","choices":["Long-term care supports ongoing care needs; hospice and palliative teams focus on comfort and may include family members, volunteers and spiritual support according to the client’s wishes.","Hospice teams do not include families, and long-term care teams do not include support workers.","Both settings use identical teams because they are in facilities.","A support worker decides which setting is medically appropriate."],"answer":[0],"explain":"Team membership varies by setting and client need. The chapter describes long-term care teams with providers, clients and families, and hospice/palliative teams that may also include volunteers and a spiritual advisor depending on the client’s wishes.","source":"Chapter 10, “Long-Term Care Facilities” and “Hospices and Palliative Care Units”; Therese’s Chapter 10 quiz study notes","originalId":"t10-08","group":"Chapter 10","bank":"Chapters 4, 5 & 10","sourceFiles":["chapter-4-5/data.js","chapter-4-5/chapter4_focus.js","chapter-4-5/chapter10.js","chapter-4-5/post_ch5_review.js","chapter-4-5/challenge_rounds.js"],"references":[]},{"id":"chapter-4-5/data.js:t10-09","chapter":10,"mode":"teamwork","topic":"Teamwork & collaboration","prompt":"A resident cannot attend a care conference. Which approach best keeps the resident at the centre of the discussion?","choices":["Share relevant firsthand observations and consider the resident’s known preferences and care needs in the team discussion.","Let the family make every decision without considering the resident’s preferences.","Skip the conference because the resident is absent.","Have the support worker decide on a new care plan."],"answer":[0],"explain":"Care conferences review needs, preferences, progress and the care plan. Support workers contribute direct observations; when the resident cannot attend, the notes emphasize keeping their known wishes in view.","source":"Therese’s Chapter 10 quiz study notes; Chapter 10, Box 10.1 and “Teamwork in Facilities”","originalId":"t10-09","group":"Chapter 10","bank":"Chapters 4, 5 & 10","sourceFiles":["chapter-4-5/data.js","chapter-4-5/chapter4_focus.js","chapter-4-5/chapter10.js","chapter-4-5/post_ch5_review.js","chapter-4-5/challenge_rounds.js"],"references":[]},{"id":"chapter-4-5/data.js:s10-01","chapter":10,"mode":"supervision","topic":"Supervision & communication","prompt":"The nurse who was supervising your shift is late returning from break and did not say who is covering. You have a question about a client’s care. What should you do?","choices":["Contact the charge nurse or designated supervisor for direction before proceeding with anything uncertain.","Ask an experienced support worker to authorize the next step in place of the nurse.","Use the previous shift’s answer because the client’s name is the same.","Wait until the original nurse returns without checking whether an alternative supervisor is available."],"answer":[0],"explain":"Follow the workplace reporting structure and seek direction from the appropriate person. If the planned supervisor is unavailable, clarify who is responsible before acting on an uncertain care issue.","source":"Chapter 10, “Working Under Supervision” and Critical Thinking in Practice; teamwork slides, “Supervision Structures”","originalId":"s10-01","group":"Chapter 10","bank":"Chapters 4, 5 & 10","sourceFiles":["chapter-4-5/data.js","chapter-4-5/chapter4_focus.js","chapter-4-5/chapter10.js","chapter-4-5/post_ch5_review.js","chapter-4-5/challenge_rounds.js"],"references":[]},{"id":"chapter-4-5/data.js:s10-02","chapter":10,"mode":"supervision","topic":"Supervision & communication","prompt":"You work for an agency providing home care. The case manager changes a client’s care plan, but the update has not reached you. Who should clarify your instructions and reporting route?","choices":["Your agency supervisor or the designated health-care team contact.","Another client who receives the same service.","A family member who is not involved in the care plan.","No one; use the previous instructions until the next scheduled visit."],"answer":[0],"explain":"In community settings, the case manager communicates with the agency, and the supervisor provides the support worker with client information and instructions. Clarify changes through the established reporting structure.","source":"Chapter 10, “Working Under Supervision”; teamwork slides, “Supervision Structures”","originalId":"s10-02","group":"Chapter 10","bank":"Chapters 4, 5 & 10","sourceFiles":["chapter-4-5/data.js","chapter-4-5/chapter4_focus.js","chapter-4-5/chapter10.js","chapter-4-5/post_ch5_review.js","chapter-4-5/challenge_rounds.js"],"references":[]},{"id":"chapter-4-5/data.js:s10-03","chapter":10,"mode":"supervision","topic":"Supervision & communication","prompt":"A client hires you directly rather than through an agency. Which step can help make each person’s responsibilities clear?","choices":["Use a written agreement acceptable to both parties, outlining responsibilities and work arrangements, and have both sign it.","Rely on informal promises so the arrangement can change without discussion.","Ask the client’s family to write rules after each shift.","Use the agency’s supervisor even though no agency is involved."],"answer":[0],"explain":"The chapter advises a written contract when a client hires a support worker directly. It should outline responsibilities and arrangements, be acceptable to both, and be signed by both parties.","source":"Chapter 10, “Working Under Supervision”; teamwork slides, “Working directly for a client”","originalId":"s10-03","group":"Chapter 10","bank":"Chapters 4, 5 & 10","sourceFiles":["chapter-4-5/data.js","chapter-4-5/chapter4_focus.js","chapter-4-5/chapter10.js","chapter-4-5/post_ch5_review.js","chapter-4-5/challenge_rounds.js"],"references":[]},{"id":"chapter-4-5/data.js:s10-04","chapter":10,"mode":"supervision","topic":"Supervision & communication","prompt":"A coworker’s remark during handoff upset you. What is the most constructive first step?","choices":["Speak respectfully with the coworker soon, in a neutral area away from clients, and describe the behaviour and concern.","Discuss the details with several coworkers to see who agrees.","Complain to the client about the coworker.","Post about the disagreement in a private online group."],"answer":[0],"explain":"The chapter recommends addressing a perceived issue promptly and respectfully in a neutral place away from clients and other workers. Avoid discussing the details with uninvolved coworkers or clients.","source":"Chapter 10, Box 10.2, “How to Effectively Resolve a Conflict with a Co-Worker”; teamwork slides, “Conflict in the Workplace”","originalId":"s10-04","group":"Chapter 10","bank":"Chapters 4, 5 & 10","sourceFiles":["chapter-4-5/data.js","chapter-4-5/chapter4_focus.js","chapter-4-5/chapter10.js","chapter-4-5/post_ch5_review.js","chapter-4-5/challenge_rounds.js"],"references":[]},{"id":"chapter-4-5/data.js:s10-05","chapter":10,"mode":"supervision","topic":"Supervision & communication","prompt":"A coworker says the team should ignore a policy they dislike. What is the best response?","choices":["Stay professional and raise your concern with the supervisor through the appropriate channel.","Join in criticizing the policy while providing client care.","Tell clients that the agency does not support its staff.","Stop following the policy until the team agrees."],"answer":[0],"explain":"The course materials advise avoiding negative discussion about workplace situations with clients or uninvolved coworkers. If unhappy about a situation, speak with the supervisor.","source":"Chapter 10, “Conflict in the Workplace” and “Respecting Your Supervisor and Employer”; teamwork slides","originalId":"s10-05","group":"Chapter 10","bank":"Chapters 4, 5 & 10","sourceFiles":["chapter-4-5/data.js","chapter-4-5/chapter4_focus.js","chapter-4-5/chapter10.js","chapter-4-5/post_ch5_review.js","chapter-4-5/challenge_rounds.js"],"references":[]},{"id":"chapter-4-5/data.js:s10-06","chapter":10,"mode":"supervision","topic":"Supervision & communication","prompt":"A client’s condition changes during a task and you are unsure what to do next. What is the safest communication step?","choices":["Stop and contact the appropriate supervisor or regulated health-care professional for timely direction.","Continue because the task was on the assignment sheet.","Ask a coworker who has not been trained to decide.","Wait until the next team meeting to mention the change."],"answer":[0],"explain":"The worker should know whom to ask for help and should report changes or problems promptly. The delegating professional must be able to provide help when the client’s condition changes.","source":"Chapter 10, Boxes 10.4–10.5 and “Accepting a Task”; teamwork slides, “Supervision Structures”","originalId":"s10-06","group":"Chapter 10","bank":"Chapters 4, 5 & 10","sourceFiles":["chapter-4-5/data.js","chapter-4-5/chapter4_focus.js","chapter-4-5/chapter10.js","chapter-4-5/post_ch5_review.js","chapter-4-5/challenge_rounds.js"],"references":[]},{"id":"chapter-4-5/data.js:s10-07","chapter":10,"mode":"supervision","topic":"Supervision & communication","prompt":"You feel intimidated speaking during a meeting with physicians and nurses, but you have relevant observations from daily care. What should you do?","choices":["Share your observations clearly and professionally; they are useful to the team’s understanding of the client.","Stay silent because only regulated professionals should contribute.","Ask a family member to report your observations for you.","Change the client’s care routine before the meeting."],"answer":[0],"explain":"Support workers are valuable team members. Their frequent contact may provide important observations, and they should express their needs and views professionally.","source":"Chapter 10, “Benefits of Working on a Team”; teamwork slides, “Challenges of Working on a Team”","originalId":"s10-07","group":"Chapter 10","bank":"Chapters 4, 5 & 10","sourceFiles":["chapter-4-5/data.js","chapter-4-5/chapter4_focus.js","chapter-4-5/chapter10.js","chapter-4-5/post_ch5_review.js","chapter-4-5/challenge_rounds.js"],"references":[]},{"id":"chapter-4-5/data.js:s10-08","chapter":10,"mode":"supervision","topic":"Supervision & communication","prompt":"You work alone in a client’s home while the nurse is off-site. A family member asks you to take on a clinical task outside your role and offers extra pay. What should guide your response?","choices":["Do not take on work outside your role; follow agency policy, use the established contact or emergency procedures, and clarify with the supervisor.","Accept because private payment overrides workplace restrictions.","Proceed because working alone expands your authority.","Ask the family member to supervise the task."],"answer":[0],"explain":"Working alone does not authorize practice outside the support worker role. Client or family requests and higher pay do not override clinical restrictions; know how to contact the supervisor and follow emergency procedures.","source":"Therese’s Chapter 10 quiz study notes; Chapter 10, “Working Under Supervision”","originalId":"s10-08","group":"Chapter 10","bank":"Chapters 4, 5 & 10","sourceFiles":["chapter-4-5/data.js","chapter-4-5/chapter4_focus.js","chapter-4-5/chapter10.js","chapter-4-5/post_ch5_review.js","chapter-4-5/challenge_rounds.js"],"references":[]},{"id":"chapter-4-5/data.js:a10-01","chapter":10,"mode":"assignment","topic":"Assignment vs. delegation","prompt":"Your supervisor asks you to help a client dress and prepare a meal, tasks listed in your job description and within your training. What is this most likely?","choices":["An assignment of care tasks within your role.","A transfer of professional authority for a controlled act.","A delegation that lets you authorize another worker.","A care conference decision."],"answer":[0],"explain":"Assigning appoints someone to take responsibility for a task within their scope of practice, job description and scope of employment. ADLs and household tasks may be assigned when they fit the worker’s role.","source":"Chapter 10, “Assigning and Delegating”; teamwork slides, “Assigning and Delegating”","originalId":"a10-01","group":"Chapter 10","bank":"Chapters 4, 5 & 10","sourceFiles":["chapter-4-5/data.js","chapter-4-5/chapter4_focus.js","chapter-4-5/chapter10.js","chapter-4-5/post_ch5_review.js","chapter-4-5/challenge_rounds.js"],"references":[]},{"id":"chapter-4-5/data.js:a10-02","chapter":10,"mode":"assignment","topic":"Assignment vs. delegation","prompt":"A client asks you to insert a urinary catheter because you once performed that task for another client. What is the best response?","choices":["Do not proceed; explain that this task requires appropriate client-specific authorization and contact your supervisor.","Proceed because your prior experience transfers to every client.","Ask the client to authorize you instead of the nurse.","Teach a coworker to do it with you."],"answer":[0],"explain":"A support worker cannot authorize or delegate tasks. Delegated activities may be client-specific and are not automatically transferable; follow employer policy and the applicable provincial or territorial rules.","source":"Chapter 10, “Assigning and Delegating” and “The Delegation Process”; teamwork slides, “The Delegation/Assigning Process”","originalId":"a10-02","group":"Chapter 10","bank":"Chapters 4, 5 & 10","sourceFiles":["chapter-4-5/data.js","chapter-4-5/chapter4_focus.js","chapter-4-5/chapter10.js","chapter-4-5/post_ch5_review.js","chapter-4-5/challenge_rounds.js"],"references":[]},{"id":"chapter-4-5/data.js:a10-03","chapter":10,"mode":"assignment","topic":"Assignment vs. delegation","prompt":"Which statement best describes delegation?","choices":["A regulated health-care professional authorizes another provider to perform a task that may otherwise be restricted to the professional.","A support worker gives a coworker permission to perform the support worker’s assigned task.","A client asks any worker to perform a task outside their role.","A team leader assigns routine duties that are already within the worker’s role."],"answer":[0],"explain":"Delegation (also called transfer of function in the text) is a process by which an authorized regulated health-care provider authorizes another provider to perform certain tasks. Support workers cannot delegate.","source":"Chapter 10, Key Terms and “Assigning and Delegating”; teamwork slides, “Assigning and Delegating”","originalId":"a10-03","group":"Chapter 10","bank":"Chapters 4, 5 & 10","sourceFiles":["chapter-4-5/data.js","chapter-4-5/chapter4_focus.js","chapter-4-5/chapter10.js","chapter-4-5/post_ch5_review.js","chapter-4-5/challenge_rounds.js"],"references":[]},{"id":"chapter-4-5/data.js:a10-04","chapter":10,"mode":"assignment","topic":"Assignment vs. delegation","prompt":"A controlled act is being considered for a client. Which statement is safest?","choices":["Only an authorized regulated professional may perform it unless the applicable rules permit proper delegation or another stated exception.","Any trained support worker may perform it whenever the client requests it.","A family member can delegate it to a support worker.","Once a nurse delegates it for one client, it automatically applies to all clients."],"answer":[0],"explain":"Controlled acts are tasks identified in legislation as requiring authority because unqualified performance may cause harm. Delegation and exceptions depend on applicable legislation, professional rules, client circumstances, employer policy and job description.","source":"Chapter 10, “Assigning and Delegating” and Box 10.3; teamwork slides, “Assigning and Delegating”","originalId":"a10-04","group":"Chapter 10","bank":"Chapters 4, 5 & 10","sourceFiles":["chapter-4-5/data.js","chapter-4-5/chapter4_focus.js","chapter-4-5/chapter10.js","chapter-4-5/post_ch5_review.js","chapter-4-5/challenge_rounds.js"],"references":[]},{"id":"chapter-4-5/data.js:a10-05","chapter":10,"mode":"assignment","topic":"Assignment vs. delegation","prompt":"A regular care activity has been performed by a nurse for a client repeatedly with consistent and safe results. Why might this matter when considering a routine activity of living?","choices":["Regular need and a history of consistent safe results are features the chapter gives for a routine activity of living.","It means the support worker can decide independently to perform any controlled act.","It makes the activity transferable to other clients.","It removes the need for employer policy and supervision."],"answer":[0],"explain":"The chapter describes a routine activity of living as something the client needs regularly and that a nurse has already performed with consistent, safe results. The worker does not decide alone whether to perform an authorized act.","source":"Chapter 10, Box 10.3, “Delegation in British Columbia, Alberta, Nova Scotia, and Ontario”; teamwork slides, “Five Rights”","originalId":"a10-05","group":"Chapter 10","bank":"Chapters 4, 5 & 10","sourceFiles":["chapter-4-5/data.js","chapter-4-5/chapter4_focus.js","chapter-4-5/chapter10.js","chapter-4-5/post_ch5_review.js","chapter-4-5/challenge_rounds.js"],"references":[]},{"id":"chapter-4-5/data.js:a10-06","chapter":10,"mode":"assignment","topic":"Assignment vs. delegation","prompt":"A task is in your job description and you have performed it before. The client now has a new, unstable condition. Can you assume the task remains appropriate?","choices":["No. The client’s current circumstances matter, and the regulated professional may need to perform or reassess the task.","Yes. Being in the job description settles the decision.","Yes, if a family member agrees.","No, because support workers can never perform assigned tasks."],"answer":[0],"explain":"The client’s needs and condition are central. A professional may decide a task requires their knowledge and judgement in the current situation, even if the support worker has done it before.","source":"Chapter 10, Boxes 10.4–10.5 and “The Delegation Process”; teamwork slides","originalId":"a10-06","group":"Chapter 10","bank":"Chapters 4, 5 & 10","sourceFiles":["chapter-4-5/data.js","chapter-4-5/chapter4_focus.js","chapter-4-5/chapter10.js","chapter-4-5/post_ch5_review.js","chapter-4-5/challenge_rounds.js"],"references":[]},{"id":"chapter-4-5/data.js:a10-07","chapter":10,"mode":"assignment","topic":"Assignment vs. delegation","prompt":"You were delegated a procedure for Client A. A second client needs the same procedure, and a coworker offers to do it using your instructions. What is the safest response?","choices":["Do not transfer the authorization or teach the coworker to perform it; ask the regulated professional for client-specific direction.","Let the coworker perform it because the steps are identical.","Authorize the coworker because the nurse authorized you.","Perform it for the second client without checking because you are competent."],"answer":[0],"explain":"A support worker cannot delegate. The text notes that rules about transfer between clients vary, and some tasks require client-specific delegation or teaching. Seek direction for the new client.","source":"Chapter 10, “The Delegation Process” and “The Support Worker’s Role in Delegation”; teamwork slides, “The Delegation/Assigning Process”","originalId":"a10-07","group":"Chapter 10","bank":"Chapters 4, 5 & 10","sourceFiles":["chapter-4-5/data.js","chapter-4-5/chapter4_focus.js","chapter-4-5/chapter10.js","chapter-4-5/post_ch5_review.js","chapter-4-5/challenge_rounds.js"],"references":[]},{"id":"chapter-4-5/data.js:a10-08","chapter":10,"mode":"assignment","topic":"Assignment vs. delegation","prompt":"A colleague has the same training as you and a similar client asks for the procedure you were taught for your assigned client. What is the correct assumption?","choices":["Do not assume the authorization transfers; delegation is specific to the client and worker, so clarify with the regulated professional.","The same diagnosis makes the delegation transferable.","Your coworker can use your authorization if you explain the steps.","The client can authorize the task in place of the delegating professional."],"answer":[0],"explain":"Delegation is specific to a particular worker and client under applicable requirements. Similar diagnoses or prior experience do not automatically authorize another worker or another client.","source":"Therese’s Chapter 10 quiz study notes; Chapter 10, “The Delegation Process” and Box 10.5","originalId":"a10-08","group":"Chapter 10","bank":"Chapters 4, 5 & 10","sourceFiles":["chapter-4-5/data.js","chapter-4-5/chapter4_focus.js","chapter-4-5/chapter10.js","chapter-4-5/post_ch5_review.js","chapter-4-5/challenge_rounds.js"],"references":[]},{"id":"chapter-4-5/data.js:d10-01","chapter":10,"mode":"delegation","topic":"Delegation safety & five rights","prompt":"A nurse considers delegating a task. The client’s condition is changing and no nurse is available to help if a problem occurs. Which delegation check is most concerning?","choices":["Right circumstances and right supervision and evaluation.","Right directions only; the other checks are satisfied.","Right person, because all support workers are excluded from delegation.","None; the nurse has already taught the procedure."],"answer":[0],"explain":"The five rights include the right circumstances and the right supervision and evaluation. The nurse considers client condition, risks, adequate supervision and timely help if problems arise.","source":"Chapter 10, Boxes 10.4–10.5; teamwork slides, “Five Rights of Delegation/Assigning”","originalId":"d10-01","group":"Chapter 10","bank":"Chapters 4, 5 & 10","sourceFiles":["chapter-4-5/data.js","chapter-4-5/chapter4_focus.js","chapter-4-5/chapter10.js","chapter-4-5/post_ch5_review.js","chapter-4-5/challenge_rounds.js"],"references":[]},{"id":"chapter-4-5/data.js:d10-02","chapter":10,"mode":"delegation","topic":"Delegation safety & five rights","prompt":"A nurse asks you to perform a delegated task, but it is not in your job description or agency policy. What should you do?","choices":["Explain your concern and clarify with the delegating professional or supervisor before proceeding.","Accept because the nurse’s request overrides your job description.","Ask the client to sign a waiver.","Ask another support worker to perform it instead."],"answer":[0],"explain":"Before accepting, check that the task is within your scope, job description and written policy. Communicate concerns to the nurse; do not ignore a request or proceed without resolving the issue.","source":"Chapter 10, Box 10.5 and “Refusing a Task”; teamwork slides, “Delegation/Assigning in the Community”","originalId":"d10-02","group":"Chapter 10","bank":"Chapters 4, 5 & 10","sourceFiles":["chapter-4-5/data.js","chapter-4-5/chapter4_focus.js","chapter-4-5/chapter10.js","chapter-4-5/post_ch5_review.js","chapter-4-5/challenge_rounds.js"],"references":[]},{"id":"chapter-4-5/data.js:d10-03","chapter":10,"mode":"delegation","topic":"Delegation safety & five rights","prompt":"You have not performed a delegated procedure often enough to feel competent, and no one is available to supervise you today. What is the safest action?","choices":["Tell the delegating professional you are not able to perform it safely now and request direction or supervision.","Perform it from memory to avoid delaying care.","Ask the client to coach you through the steps.","Ignore the task without telling anyone."],"answer":[0],"explain":"The worker should consider current competence, frequency of practice and available supervision. A worker may refuse for a sound safety reason, but should communicate concerns rather than ignore the request.","source":"Chapter 10, Boxes 10.4–10.5 and “Refusing a Task”; teamwork slides, “Your Role in Delegation/Assigning”","originalId":"d10-03","group":"Chapter 10","bank":"Chapters 4, 5 & 10","sourceFiles":["chapter-4-5/data.js","chapter-4-5/chapter4_focus.js","chapter-4-5/chapter10.js","chapter-4-5/post_ch5_review.js","chapter-4-5/challenge_rounds.js"],"references":[]},{"id":"chapter-4-5/data.js:d10-04","chapter":10,"mode":"delegation","topic":"Delegation safety & five rights","prompt":"You accept a delegated care activity and complete it. What remains part of your responsibility?","choices":["Perform it safely, report what you did and your observations, and seek help if unsure or if a problem arises.","Assume the nurse is solely responsible for every action you take.","Document only if the outcome was unexpected.","Ask a coworker to decide what information to report."],"answer":[0],"explain":"The regulated professional has responsibilities for teaching, supervision and monitoring, and the support worker remains accountable for their own actions. Report what was done and relevant observations.","source":"Chapter 10, “Who Can Delegate?”, “Accepting a Task”; teamwork slides, “Your Role in Delegation/Assigning”","originalId":"d10-04","group":"Chapter 10","bank":"Chapters 4, 5 & 10","sourceFiles":["chapter-4-5/data.js","chapter-4-5/chapter4_focus.js","chapter-4-5/chapter10.js","chapter-4-5/post_ch5_review.js","chapter-4-5/challenge_rounds.js"],"references":[]},{"id":"chapter-4-5/data.js:d10-05","chapter":10,"mode":"delegation","topic":"Delegation safety & five rights","prompt":"A client who usually tolerates a delegated task becomes confused and resists when you begin. What should you do?","choices":["Stop and contact the appropriate health-care professional because the client’s condition or response has changed.","Continue because the task was authorized on a previous visit.","Ask the client’s family to hold the client still.","Finish quickly and report it only if an injury occurs."],"answer":[0],"explain":"Delegation decisions depend on the client’s current circumstances. A changed condition or response is a sound reason to stop and seek direction; the professional must be available to help when problems arise.","source":"Chapter 10, Boxes 10.4–10.5 and “Refusing a Task”; teamwork slides, “Your Role in Delegation/Assigning”","originalId":"d10-05","group":"Chapter 10","bank":"Chapters 4, 5 & 10","sourceFiles":["chapter-4-5/data.js","chapter-4-5/chapter4_focus.js","chapter-4-5/chapter10.js","chapter-4-5/post_ch5_review.js","chapter-4-5/challenge_rounds.js"],"references":[]},{"id":"chapter-4-5/data.js:d10-06","chapter":10,"mode":"delegation","topic":"Delegation safety & five rights","prompt":"A task is permitted for support workers in one province, but you are working in a different province. What should you check before accepting it?","choices":["The legislation, employer policy and job description that apply where you are working, then clarify with the supervisor.","Only whether you performed the task in the first province.","Whether the client has seen another worker do it.","Nothing; delegation rules are identical across Canada."],"answer":[0],"explain":"Delegation guidelines vary across provinces and territories. Know the rules in your location as well as employer policy and the tasks included in your job description.","source":"Chapter 10, Box 10.3 and “The Delegation Process”; teamwork slides, “The Delegation/Assigning Process”","originalId":"d10-06","group":"Chapter 10","bank":"Chapters 4, 5 & 10","sourceFiles":["chapter-4-5/data.js","chapter-4-5/chapter4_focus.js","chapter-4-5/chapter10.js","chapter-4-5/post_ch5_review.js","chapter-4-5/challenge_rounds.js"],"references":[]},{"id":"chapter-4-5/data.js:d10-07","chapter":10,"mode":"delegation","topic":"Delegation safety & five rights","prompt":"You do not want to complete a delegated task because it is unpleasant, but you are trained, the client is stable, and appropriate supervision is available. What is the most appropriate response?","choices":["Disliking the task alone is not a sound reason to refuse; raise any genuine concern, otherwise perform it as directed.","Refusal is always appropriate whenever a worker does not like a task.","Ask the client to find a different worker without notifying the nurse.","Delegate the task to a coworker."],"answer":[0],"explain":"Workers may refuse with sound reasons such as competence concerns, a task beyond scope, or a changed client condition. The text says not to refuse simply because you do not like or want to do the task; communicate with the professional if you have concerns.","source":"Chapter 10, “Refusing a Task”; teamwork slides, “Refusing a Care activity”","originalId":"d10-07","group":"Chapter 10","bank":"Chapters 4, 5 & 10","sourceFiles":["chapter-4-5/data.js","chapter-4-5/chapter4_focus.js","chapter-4-5/chapter10.js","chapter-4-5/post_ch5_review.js","chapter-4-5/challenge_rounds.js"],"references":[]},{"id":"chapter-4-5/data.js:d10-08","chapter":10,"mode":"delegation","topic":"Delegation safety & five rights","prompt":"Before delegating a task, a nurse considers client condition and risks, worker competence, supervision, and whether the task fits the job description. Which additional factor does the chapter include?","choices":["Whether a nurse is available to help if the client’s condition changes or a problem arises.","Whether the worker prefers the task.","Whether the client has the same diagnosis as another client.","Whether a family member can explain the task."],"answer":[0],"explain":"Box 10.4 lists five considerations. The fourth is whether a nurse is available to help if the client’s condition changes or problems arise. This is verified against the supplied Chapter 10 text.","source":"Chapter 10, Box 10.4; Therese’s notes flag the fourth factor for textbook verification","originalId":"d10-08","group":"Chapter 10","bank":"Chapters 4, 5 & 10","sourceFiles":["chapter-4-5/data.js","chapter-4-5/chapter4_focus.js","chapter-4-5/chapter10.js","chapter-4-5/post_ch5_review.js","chapter-4-5/challenge_rounds.js"],"references":[]},{"id":"chapter-4-5/data.js:d10-09","chapter":10,"mode":"delegation","topic":"Delegation safety & five rights","prompt":"You have accepted a delegated task. Which sequence captures three core responsibilities emphasized for the support worker?","choices":["Understand the responsibilities and limits, know when and whom to ask, and know when, how and to whom to report.","Authorize, supervise and evaluate another worker.","Diagnose, treat and independently revise the care plan.","Accept, complete and transfer the task to a colleague."],"answer":[0],"explain":"Before performing a delegated activity, the worker must understand the responsibilities, know when and whom to ask for help, and know when, how and to whom to report the outcome. This is summarized in the lecture notes as UAR: Understand, Ask, Report.","source":"Chapter 10, “Assigning and Delegating”; Therese’s Chapter 10 quiz study notes","originalId":"d10-09","group":"Chapter 10","bank":"Chapters 4, 5 & 10","sourceFiles":["chapter-4-5/data.js","chapter-4-5/chapter4_focus.js","chapter-4-5/chapter10.js","chapter-4-5/post_ch5_review.js","chapter-4-5/challenge_rounds.js"],"references":[]},{"id":"chapter-4-5/data.js:d10-10","chapter":10,"mode":"delegation","topic":"Delegation safety & five rights","prompt":"The workload is too heavy to complete an assigned task safely. A coworker offers to take it without supervisor approval. What should you do?","choices":["Notify the supervisor with factual details and seek appropriate help rather than silently transferring the task.","Transfer it to the coworker because both work for the same employer.","Skip the task and do not tell anyone.","Ask the client to choose which task should be missed."],"answer":[0],"explain":"The lecture notes emphasize communicating workload concerns and seeking appropriate help rather than silently transferring a task. Support workers cannot pass a delegated task to another worker.","source":"Therese’s Chapter 10 quiz study notes; Chapter 10, “The Support Worker’s Role in Delegation”","originalId":"d10-10","group":"Chapter 10","bank":"Chapters 4, 5 & 10","sourceFiles":["chapter-4-5/data.js","chapter-4-5/chapter4_focus.js","chapter-4-5/chapter10.js","chapter-4-5/post_ch5_review.js","chapter-4-5/challenge_rounds.js"],"references":[]},{"id":"chapter-4-5/data.js:d10-11","chapter":10,"mode":"delegation","topic":"Delegation safety & five rights","prompt":"A nurse is off-site during a home visit. Which question matters most before accepting a delegated task?","choices":["Can I be adequately supervised here, and is reliable help available if the client’s condition changes or a problem arises?","Have I ever performed a similar task for anyone?","Does the family prefer that I do it?","Will accepting it save the agency time?"],"answer":[0],"explain":"Adequate supervision and timely assistance are central factors in the nurse’s delegation decision. A support worker must also know whom to contact and seek clarification if the required support is not available.","source":"Chapter 10, Box 10.4; Therese’s Chapter 10 quiz study notes","originalId":"d10-11","group":"Chapter 10","bank":"Chapters 4, 5 & 10","sourceFiles":["chapter-4-5/data.js","chapter-4-5/chapter4_focus.js","chapter-4-5/chapter10.js","chapter-4-5/post_ch5_review.js","chapter-4-5/challenge_rounds.js"],"references":[]},{"id":"chapter-4-5/data.js:d10-12","chapter":10,"mode":"delegation","topic":"Delegation safety & five rights","prompt":"A coworker who is not involved in a resident’s care asks for details about the resident’s condition. What is the best response?","choices":["Share only with team members who need the information for care, through an appropriate private channel.","Share because everyone at the same facility has automatic access to every client’s information.","Discuss it in the staff room to avoid disturbing the resident.","Give the coworker the details if they promise not to repeat them."],"answer":[0],"explain":"Colleagues at the same organization do not automatically need to know every client detail. Keep identifiable information private and limit sharing to appropriate care-related channels.","source":"Therese’s Chapter 10 quiz study notes; Chapter 10, “Benefits of Working on a Team”","originalId":"d10-12","group":"Chapter 10","bank":"Chapters 4, 5 & 10","sourceFiles":["chapter-4-5/data.js","chapter-4-5/chapter4_focus.js","chapter-4-5/chapter10.js","chapter-4-5/post_ch5_review.js","chapter-4-5/challenge_rounds.js"],"references":[]},{"id":"chapter-4-5/data.js:d10-13","chapter":10,"mode":"delegation","topic":"Delegation safety & five rights","prompt":"Which set lists all five rights of delegation?","choices":["Right Task; Right Circumstances; Right Person; Right Directions and Communication; Right Supervision and Evaluation.","Right Client; Right Diagnosis; Right Worker; Right Equipment; Right Outcome.","Right Task; Right Nurse; Right Family; Right Schedule; Right Documentation.","Right Person; Right Pay; Right Setting; Right Consent; Right Referral."],"answer":[0],"explain":"The five rights are Right Task, Right Circumstances, Right Person, Right Directions and Communication, and Right Supervision and Evaluation.","source":"Teamwork slides, “Five Rights of Delegation/Assigning” (Slide 23); Chapter 10, Boxes 10.4–10.5; Complete Chapter 10 Quiz Study Guide","originalId":"d10-13","group":"Chapter 10","bank":"Chapters 4, 5 & 10","sourceFiles":["chapter-4-5/data.js","chapter-4-5/chapter4_focus.js","chapter-4-5/chapter10.js","chapter-4-5/post_ch5_review.js","chapter-4-5/challenge_rounds.js"],"references":[]},{"id":"chapter-4-5/data.js:d10-14","chapter":10,"mode":"delegation","topic":"Delegation safety & five rights","prompt":"During a home visit, you cannot reach the off-site nurse and the directions do not say whom to contact after hours. Which delegation rights need attention?","choices":["Right Directions and Communication, and Right Supervision and Evaluation.","Right Person only.","Right Task only.","None, because the task was authorized before the visit."],"answer":[0],"explain":"Directions must make contacts and reporting requirements clear, and adequate supervision and help must be available. Do not proceed automatically when necessary direction or support is missing.","source":"Teamwork slides, “Five Rights of Delegation/Assigning”; Therese’s Complete Chapter 10 Quiz Study Guide","originalId":"d10-14","group":"Chapter 10","bank":"Chapters 4, 5 & 10","sourceFiles":["chapter-4-5/data.js","chapter-4-5/chapter4_focus.js","chapter-4-5/chapter10.js","chapter-4-5/post_ch5_review.js","chapter-4-5/challenge_rounds.js"],"references":[]}]);
